window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[330]={"id":"330","numero":330,"titre":"Prescription & surveillance des classes de médicaments","objectifs":[{"id":"330-1","rang":"A","rubrique":"Prise en charge","titre":"Anti-inflammatoires non stéroïdiens et les corticoïdes par voie générale ou locale : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p>Cet objectif couvre <strong>deux familles d'anti-inflammatoires</strong> : <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">AINS</span> (non stéroïdiens) et les <span class=\"kw-def\">corticoïdes</span> (stéroïdiens), ces derniers par voie générale comme par voie locale.</p>\n\n      <p><strong>A — Anti-inflammatoires non stéroïdiens (<span class=\"kw-ttt\">AINS</span>).</strong></p>\n      <p><strong>Mécanisme.</strong> Tous <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AINS</span> inhibent les <span class=\"kw-def\">cyclo-oxygénases</span> (COX-1 et COX-2), bloquant la production des <span class=\"kw-def\">prostanoïdes</span> (prostaglandines et thromboxanes) issus de l'acide arachidonique.</p>\n      <table >\n        <thead><tr><th>—</th><th>COX-1</th><th>COX-2</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Profil</strong></td><td>Enzyme <span class=\"kw-def\">constitutive</span> (presque tous <span class=\"kw-clinique\">les</span> tissus)</td><td>Enzyme <span class=\"kw-def\">inductible</span> dans l'inflammation</td></tr>\n          <tr><td><strong>Rôle physiologique</strong></td><td>Protection de la muqueuse gastrique ; maintien de la perfusion rénale ; thromboxane proagrégant</td><td><span class=\"kw-clinique\">Fièvre</span>, douleur, inflammation ; perfusion rénale ; protection vasculaire (vasodilatation, anti-agrégation)</td></tr>\n          <tr><td><strong>Conséquence de l'inhibition</strong></td><td><span class=\"kw-alerte\">Ulcère gastro-duodénal</span> ; <span class=\"kw-alerte\">insuffisance rénale</span> ; effet anti-agrégant</td><td>Effet anti-pyrétique, <span class=\"kw-ttt\">antalgique</span>, anti-<span class=\"kw-etio\">inflammatoire</span> ; <span class=\"kw-alerte\">risque pro-thrombotique</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Familles.</strong> <span class=\"kw-ttt\">Anti-COX-1 préférentiels</span> (<span class=\"kw-ttt\">aspirine</span> à faible dose, indométacine, piroxicam) ; <span class=\"kw-ttt\">AINS non sélectifs</span> (<span class=\"kw-ttt\">ibuprofène</span>, <span class=\"kw-ttt\">kétoprofène</span>) ; <span class=\"kw-ttt\">coxibs</span> = anti-COX-2 sélectifs (célécoxib, parécoxib) et diclofénac — moins ulcérogènes mais <span class=\"kw-alerte\">plus pro-thrombotiques</span>.</p>\n      <p><strong>Effets thérapeutiques et indications.</strong> Anti-pyrétique ; <span class=\"kw-ttt\">antalgique</span> (effet plateau, posologies faibles) ; anti-<span class=\"kw-etio\">inflammatoire</span> (posologies plus élevées). Indications : douleurs ostéo-articulaires, accès microcristallins, rhumatismes inflammatoires en <span class=\"kw-clinique\">poussée</span>, coliques néphrétiques, dysménorrhées, <span class=\"kw-def\">migraine</span>.</p>\n      <p><strong>Effets indésirables.</strong></p>\n      <table >\n        <thead><tr><th>Système</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Digestif</strong></td><td><span class=\"kw-clinique\">Épigastralgies</span>, dyspepsie ; <span class=\"kw-alerte\">ulcère gastro-duodénal</span> (asymptomatique dans <span class=\"kw-chiffre\">50 %</span> des cas) ; ulcérations du grêle et du côlon (perforation, hémorragie)</td></tr>\n          <tr><td><strong>Rénal</strong></td><td><span class=\"kw-alerte\">IRA fonctionnelle</span> (sujet âgé, hypovolémie) ; néphropathie tubulo-interstitielle immuno-<span class=\"kw-etio\">allergique</span> ; <span class=\"kw-clinique\">nécrose</span> papillaire</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Ionogramme</span></strong></td><td><span class=\"kw-alerte\">Hyperkaliémie</span> ; rétention hydrosodée (<span class=\"kw-def\">HTA</span>, <span class=\"kw-clinique\">œdème</span>)</td></tr>\n          <tr><td><strong>Cardiovasculaire</strong></td><td><span class=\"kw-def\">HTA</span> ; <span class=\"kw-alerte\">décompensation</span> d'<span class=\"kw-def\">insuffisance cardiaque</span> ; <span class=\"kw-alerte\">thrombose artérielle</span> (surtout coxibs et diclofénac)</td></tr>\n          <tr><td><strong>Gynéco-obstétrical</strong></td><td><span class=\"kw-alerte\">Fermeture prématurée du canal artériel</span> ; oligoamnios par IR fœtale (à partir du 6e mois)</td></tr>\n          <tr><td><strong><span class=\"kw-ci\">Allergie</span></strong></td><td>Toxidermie, bronchospasme, <span class=\"kw-alerte\">syndrome de Fernand Widal</span> (<span class=\"kw-def\">asthme</span> + polypose + <span class=\"kw-ci\">allergie</span> à l'<span class=\"kw-ttt\">aspirine</span>)</td></tr>\n          <tr><td><strong>Infection</strong></td><td>Aggravation des infections virales (varicelle, <span class=\"kw-etio\">grippe</span>) et à <span class=\"kw-alerte\">bactéries pyogènes</span> (dermo-hypodermite, infection ORL)</td></tr>\n          <tr><td><strong>Autres</strong></td><td><span class=\"kw-def\">Syndrome confusionnel</span> du sujet âgé ; <span class=\"kw-clinique\">hypoglycémie</span> ; <span class=\"kw-def\">hépatite</span> ; thrombopathie</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ci\">Contre-indications</span>.</strong></p>\n      <ul>\n        <li><span class=\"kw-ci\">Ulcère gastro-duodénal évolutif</span>, ATCD d'<span class=\"kw-clinique\">UGD</span> ou d'hémorragie digestive récurrente</li>\n        <li><span class=\"kw-ci\">Insuffisance rénale</span>, <span class=\"kw-alerte\">insuffisance hépatocellulaire</span> sévère, <span class=\"kw-def\">insuffisance cardiaque</span> sévère</li>\n        <li>Infection évolutive ; maladie <span class=\"kw-etio\">hémorragique</span> ; <span class=\"kw-ci\">allergie</span> / <span class=\"kw-ci\">syndrome de Widal</span></li>\n        <li><strong><span class=\"kw-ci\">Grossesse à partir de 6 mois (24 SA)</span></strong> : CI formelle de tous <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AINS</span>, toutes voies sauf collyre (canal artériel, oligoamnios, hémorragie fœtale)</li>\n        <li>Coxibs et diclofénac : CI durant toute la <span class=\"kw-ci\">grossesse</span>, et si ATCD d'<span class=\"kw-def\">AVC</span>/<span class=\"kw-def\">AIT</span>, cardiopathie <span class=\"kw-etio\">ischémique</span> ou AOMI</li>\n      </ul>\n      <p><strong>Interactions.</strong> <span class=\"kw-ttt\">AVK</span> (piroxicam et <span class=\"kw-ttt\">aspirine</span> anti-<span class=\"kw-etio\">inflammatoire</span> = association <span class=\"kw-ci\">contre-indiquée</span> ; autres <span class=\"kw-ttt\">AINS</span> = déconseillée) ; <span class=\"kw-ttt\">antiagrégants</span> et <span class=\"kw-ttt\">ISRS</span> (hémorragie digestive) ; <span class=\"kw-ttt\">lithium</span> (élévation de la lithémie) ; <span class=\"kw-ttt\">IEC/ARA2 + diurétiques</span> (<span class=\"kw-def\">IRA</span> chez le sujet âgé ou déshydraté) ; <span class=\"kw-ttt\">méthotrexate</span> à forte dose.</p>\n      <p><strong><span class=\"kw-def\">Surveillance</span> et causes d'échec.</strong> Traitement prolongé : PA, poids, <span class=\"kw-clinique\">œdème</span>, <span class=\"kw-bio\">hémoglobine</span>, <span class=\"kw-bio\">DFG</span>, transaminases, lithémie. Règles : jamais 2 <span class=\"kw-ttt\">AINS</span> associés ; <strong>jamais à jeun, toujours avec un verre d'eau en position debout</strong> ; pas de prescription au long cours ; l'échec d'un <span class=\"kw-ttt\">AINS</span> ne préjuge pas de l'efficacité d'un autre ; <span class=\"kw-ttt\">IPP</span> préventif si 1-2 <span class=\"kw-def\">facteurs de risque</span> digestif, <span class=\"kw-ttt\">AINS</span> <span class=\"kw-ci\">à éviter</span> si <span class=\"kw-chiffre\">≥ 3</span> facteurs. Enfant : <span class=\"kw-ttt\">ibuprofène</span> AMM dès <span class=\"kw-chiffre\">3 mois</span>, <span class=\"kw-ttt\">kétoprofène</span> IV dès <span class=\"kw-chiffre\">15 ans</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le trépied <span class=\"kw-alerte\">AINS + IEC/ARA2 + diurétique</span> chez un sujet âgé déshydraté entraîne une <span class=\"kw-alerte\">insuffisance rénale aiguë fonctionnelle</span> — vérifier systématiquement <span class=\"kw-clinique\">les</span> co-prescriptions avant tout <span class=\"kw-ttt\">AINS</span>.</div>\n\n      <p><strong>B — <span class=\"kw-ttt\">Corticoïdes</span> par voie générale.</strong></p>\n      <p><strong>Définition et molécules.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">corticoïdes</span> sont des <span class=\"kw-def\">anti-inflammatoires stéroïdiens</span> (glucocorticoïdes), dérivés synthétiques du <span class=\"kw-def\">cortisol</span>. La <span class=\"kw-ttt\">prednisone</span> est la molécule de référence.</p>\n      <table >\n        <thead><tr><th>Molécule</th><th>Équivalence anti-<span class=\"kw-etio\">inflammatoire</span></th><th>Activité minéralocorticoïde</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Hydrocortisone</span> (non fluoré)</td><td><span class=\"kw-chiffre\">20 mg</span></td><td>Présente</td></tr>\n          <tr><td><span class=\"kw-ttt\">Prednisone / prednisolone</span> (non fluorés)</td><td><span class=\"kw-chiffre\">5 mg</span></td><td>Faible</td></tr>\n          <tr><td><span class=\"kw-ttt\">Méthylprednisolone</span> (non fluoré)</td><td><span class=\"kw-chiffre\">4 mg</span></td><td>Faible</td></tr>\n          <tr><td><span class=\"kw-ttt\">Bétaméthasone / dexaméthasone</span> (fluorés)</td><td><span class=\"kw-chiffre\">0,75 mg</span></td><td><span class=\"kw-alerte\">Nulle</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Propriétés.</strong> Effet anti-<span class=\"kw-etio\">inflammatoire</span> dès <span class=\"kw-clinique\">les</span> faibles doses ; effet <span class=\"kw-ttt\">immunosuppresseur</span> et anti-<span class=\"kw-etio\">allergique</span> aux posologies plus élevées ; effet <span class=\"kw-ttt\">antalgique</span> uniquement s'il existe une inflammation.</p>\n      <p><strong>Effets indésirables</strong> (fréquence et gravité dépendent de la dose et de la durée).</p>\n      <table >\n        <thead><tr><th>Système</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Cutané</strong></td><td>Atrophie, vergetures, <span class=\"kw-def\">purpura</span> de Bateman — possibles <strong>même à faible dose</strong></td></tr>\n          <tr><td><strong>Métabolique</strong></td><td><span class=\"kw-etio\">Obésité</span> facio-tronculaire, prise de poids ; <span class=\"kw-alerte\">décompensation d'un diabète</span> ; hyperlipidémie</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Infectieux</span></strong></td><td>Réactivation d'infection latente (<span class=\"kw-def\">tuberculose</span>, anguillulose, herpès) ; germes opportunistes (pneumocystose)</td></tr>\n          <tr><td><strong>Oculaire</strong></td><td><span class=\"kw-clinique\">Cataracte sous-capsulaire postérieure</span> ; glaucome / <span class=\"kw-clinique\">hypertension</span> intra-oculaire</td></tr>\n          <tr><td><strong>Neuropsychique</strong></td><td>Insomnie, excitation ; troubles psychiatriques précoces aux fortes doses</td></tr>\n          <tr><td><strong>Ostéo-articulaire</strong></td><td><span class=\"kw-alerte\">Ostéoporose cortico-induite</span> ; ostéonécrose aseptique de la tête fémorale ; <span class=\"kw-alerte\">rupture</span> tendineuse ; retard de croissance</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">NFS</span></strong></td><td><span class=\"kw-bio\">Polynucléose neutrophile</span> ; éosinopénie ; lymphopénie</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Ionogramme</span></strong></td><td><span class=\"kw-alerte\">Hypokaliémie</span> (effet minéralocorticoïde, surtout en début de traitement)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> L'<span class=\"kw-alerte\">ostéoporose cortico-induite</span> n'est PAS un effet secondaire d'une <span class=\"kw-ttt\">corticothérapie</span> de quelques jours. De même, sous <span class=\"kw-ttt\">corticoïdes</span>, une <span class=\"kw-bio\">polynucléose neutrophile isolée</span> n'est pas un argument en faveur d'une infection.</div>\n      <p><strong>Règle d'or et <span class=\"kw-ttt\">corticothérapie</span> courte.</strong> Dose la plus faible, durée la plus courte possible. Une <span class=\"kw-ttt\">corticothérapie</span> courte (<span class=\"kw-chiffre\">&lt; 21 jours</span>) expose peu, mais surveiller <span class=\"kw-clinique\">les</span> complications précoces : aggravation d'une infection active, <span class=\"kw-alerte\">anguillulose maligne</span>, déséquilibre du <span class=\"kw-def\">diabète</span>, <span class=\"kw-alerte\">décompensation</span> d'IC, <span class=\"kw-def\">HTA</span>, ostéonécrose, troubles psychiatriques. <span class=\"kw-ttt\">Corticoïdes</span> non fluorés, prise unique le matin, arrêt brutal possible.</p>\n      <p><strong><span class=\"kw-ci\">Contre-indications</span>.</strong> Il n'existe pas d'<span class=\"kw-ci\">interdit</span> absolu si <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">corticoïdes</span> sont indispensables (évaluation bénéfice/risque). L'<span class=\"kw-ci\">infection patente</span> est une CI au moins transitoire. <span class=\"kw-ci\">Grossesse</span> : <span class=\"kw-ttt\">corticoïdes</span> non tératogènes — privilégier <span class=\"kw-ttt\">prednisone</span>/<span class=\"kw-ttt\">prednisolone</span> (faible passage placentaire).</p>\n      <p><strong><span class=\"kw-ci\">Bilan pré-thérapeutique</span></strong> (<span class=\"kw-ttt\">corticothérapie</span> prolongée) : poids, IMC, PA, recherche de foyers <span class=\"kw-etio\">infectieux</span> ; <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme</span>, bilan phosphocalcique, <span class=\"kw-bio\">25-OH-vitamine D</span>, <span class=\"kw-bio\"><span class=\"kw-bio\">glycémie</span> à jeun</span>, <span class=\"kw-bio\">bilan lipidique</span>, <span class=\"kw-bio\">bandelette urinaire</span>, <span class=\"kw-imagerie\">RXT</span>. <strong>Pas de <span class=\"kw-bio\">créatininémie</span></strong> : <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">corticoïdes</span> ne sont pas néphrotoxiques.</p>\n      <p><strong>Mesures adjuvantes</strong> (doses <span class=\"kw-chiffre\">&gt; 10 mg/j</span>) : mesures hygiéno-diététiques (limitation du sel adaptée au <span class=\"kw-def\">terrain</span>, limiter <span class=\"kw-clinique\">les</span> sucres rapides, apport protidique — <strong>pas de régime sans sel strict</strong>, risque de dénutrition chez le sujet âgé) ; <span class=\"kw-ttt\">ivermectine</span> si voyage en zone d'endémie (anguillulose maligne) ; vaccins antigrippal et antipneumococcique ; <strong><span class=\"kw-ci\">vaccins vivants contre-indiqués si ≥ 10 mg/j</span></strong> ; risque osseux : calcium/<span class=\"kw-bio\">vitamine D</span> si apports insuffisants, ostéodensitométrie si <span class=\"kw-ttt\">corticothérapie</span> orale &gt;<span class=\"kw-chiffre\"> 3 mois</span>, traitement anti-ostéoporotique si <span class=\"kw-chiffre\">≥ 7,5 mg/j pendant ≥ 3 mois</span> selon le T-<span class=\"kw-def\">score</span> (<span class=\"kw-chiffre\">≤ -1,5</span>).</p>\n      <p><strong><span class=\"kw-def\">Surveillance</span>.</strong> <span class=\"kw-bio\">Glycémie</span> quelques jours après le début ; <span class=\"kw-bio\">kaliémie</span> à<span class=\"kw-chiffre\"> 1-2 semaines</span> ; <span class=\"kw-bio\">bilan lipidique</span> à<span class=\"kw-chiffre\"> 6 mois</span> ; <span class=\"kw-bio\">HbA1c</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> si <span class=\"kw-def\">diabète</span> ; ostéodensitométrie à<span class=\"kw-chiffre\"> 1 an</span>.</p>\n      <p><strong><span class=\"kw-ttt\">Sevrage</span> et causes d'échec.</strong> L'arrêt brutal d'une <span class=\"kw-ttt\">corticothérapie</span> prolongée expose à une <span class=\"kw-alerte\">insuffisance corticotrope</span> ; <span class=\"kw-ttt\">sevrage</span> envisagé à partir de <span class=\"kw-chiffre\">5 mg</span>/j de <span class=\"kw-ttt\">prednisone</span>, avec substitution par <span class=\"kw-ttt\">hydrocortisone</span>. Causes d'échec : erreur diagnostique, maladie cortico-résistante, <strong>mauvaise observance</strong> (suspectée devant l'absence de signes d'imprégnation : Cushing, lymphopénie, éosinopénie).</p>\n\n      <p><strong>C — <span class=\"kw-ttt\">Corticoïdes</span> par voie locale.</strong></p>\n      <p><strong><span class=\"kw-ttt\">Dermocorticoïdes</span>.</strong> Classés en <span class=\"kw-chiffre\">4 niveaux</span> d'activité anti-<span class=\"kw-etio\">inflammatoire</span> (I faible → IV très forte), selon le test de vasoconstriction de McKenzie. Indications : <span class=\"kw-clinique\">eczéma</span> et <span class=\"kw-etio\">dermatite atopique</span>, <span class=\"kw-clinique\">psoriasis</span>, pemphigoïde bulleuse, lichen, <span class=\"kw-def\">lupus</span> érythémateux chronique, vitiligo, pelade. <span class=\"kw-ci\">Contre-indications</span> : dermatoses infectieuses, lésions ulcérées, acné, rosacée, application sur <span class=\"kw-clinique\">les</span> paupières (glaucome). Effets indésirables : <span class=\"kw-alerte\">atrophie cutanée</span>, <span class=\"kw-clinique\">dermatite</span> rosacéiforme / péri-orale induite, glaucome et cataracte si application aux paupières, effets systémiques (surtout chez l'enfant). Galénique : pommade (lésions sèches, jamais sur les plis), crème (préférée), gel/lotion (plis et zones pileuses). Une seule application par jour suffit (effet réservoir) ; arrêt progressif si dermatose chronique (rebond) ; tachyphylaxie.</p>\n      <p><strong>Infiltrations de <span class=\"kw-ttt\">corticoïdes</span>.</strong> Indications : syndrome du canal carpien, tendinopathies (péri-articulaire), arthrite ou arthrose en <span class=\"kw-clinique\">poussée</span> (intra-articulaire), radiculalgies (épidurale). <span class=\"kw-ci\">Contre-indications</span> : infection locale, générale, articulaire ou de voisinage ; troubles de la coagulation ; prothèse ou matériel d'<span class=\"kw-ttt\">ostéosynthèse</span>. Complications : <span class=\"kw-alerte\">rupture</span> tendineuse ; <span class=\"kw-clinique\">arthrite microcristalline</span> (&lt;<span class=\"kw-chiffre\"> 24 h</span>, régresse en <span class=\"kw-chiffre\">1-2 jours</span>) à distinguer de l'<span class=\"kw-alerte\">arthrite septique</span> (&gt;<span class=\"kw-chiffre\"> 24 h</span>, analyse bactériologique du liquide synovial impérative).</p>","frequence":5},{"id":"330-2","rang":"A","rubrique":"Prise en charge","titre":"Diurétiques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">diurétiques</span> augmentent l'excrétion urinaire de sodium et d'eau ; ils se distinguent par leur site d'action sur le néphron et leur retentissement sur la <span class=\"kw-bio\">kaliémie</span>.</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Cible / molécules</th><th><span class=\"kw-bio\">Kaliémie</span></th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Acétazolamide</strong></td><td><span class=\"kw-def\">Anhydrase carbonique</span> (tube proximal)</td><td><span class=\"kw-alerte\">Hypokaliémie</span></td><td>Glaucome aigu, mal des montagnes</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Diurétiques</span> de l'anse</strong></td><td><span class=\"kw-def\">NKCC2</span> (branche ascendante) — <span class=\"kw-ttt\">furosémide</span>, <span class=\"kw-ttt\">bumétanide</span></td><td><span class=\"kw-alerte\">Hypokaliémie ++</span></td><td>Surcharge hydrosodée ; seuls actifs si <span class=\"kw-bio\">DFG &lt; 30 mL/min</span></td></tr>\n          <tr><td><strong>Thiazidiques</strong></td><td>Co-transporteur <span class=\"kw-def\">NaCl</span> (tube distal) — <span class=\"kw-ttt\">hydrochlorothiazide</span>, indapamide</td><td><span class=\"kw-alerte\">Hypokaliémie</span></td><td><span class=\"kw-def\">HTA</span> (sauf <span class=\"kw-bio\">DFG</span> &lt;<span class=\"kw-chiffre\"> 30 mL</span>/min)</td></tr>\n          <tr><td><strong>Épargneurs de potassium</strong></td><td><span class=\"kw-ttt\">Spironolactone</span> (anti-aldostérone), amiloride (ENaC)</td><td><span class=\"kw-alerte\">Hyperkaliémie</span></td><td>IC à FEVG altérée NYHA 2-4, hyperaldostéronisme primaire, <span class=\"kw-def\">cirrhose</span> œdémato-ascitique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Effets indésirables.</strong> Anse et thiazidiques : <span class=\"kw-alerte\">déshydratation extracellulaire</span>, hyponatrémie, hypokaliémie, hypomagnésémie, hyperuricémie, hyperglycémie ; thiazidiques en plus : hypercalcémie, effet photosensibilisant. Épargneurs : <span class=\"kw-alerte\">hyperkaliémie</span>, <span class=\"kw-ci\">insuffisance rénale</span> ; <span class=\"kw-ttt\">spironolactone</span> : <span class=\"kw-clinique\">gynécomastie</span>, troubles menstruels, dysfonction érectile.</p>\n      <p><strong><span class=\"kw-def\">Surveillance</span>.</strong> <span class=\"kw-ci\">Bilan pré-thérapeutique</span> : <span class=\"kw-bio\">créatininémie + DFG</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">uricémie</span>, <span class=\"kw-bio\">glycémie</span>. <span class=\"kw-bio\">Ionogramme</span> à <span class=\"kw-chiffre\">J15</span>, M1, puis 1-2×/an, et à chaque modification de posologie ou événement intercurrent. Régime hyposodé toujours associé.</p>\n      <p><strong>Interactions et causes d'échec.</strong> Diminution de la <span class=\"kw-bio\">clairance</span> du <span class=\"kw-ttt\">lithium</span> ; <span class=\"kw-ttt\">AINS</span> qui réduisent l'effet <span class=\"kw-ttt\">diurétique</span> ; médicaments allongeant le QT (l'hypokaliémie favorise la torsade de pointe). <span class=\"kw-ci\">Contre-indication</span> : <span class=\"kw-ci\">grossesse</span> (hypoperfusion fœtale). L'échec est fréquent si le régime hyposodé n'est pas <span class=\"kw-def\">suivi</span>, ou si des thiazidiques sont utilisés à tort alors que le <span class=\"kw-bio\">DFG</span> est &lt;<span class=\"kw-chiffre\"> 30 mL</span>/min.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-def\">HTA</span> · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span></em></p>","frequence":2},{"id":"330-3","rang":"A","rubrique":"Prise en charge","titre":"Bêta-bloquants : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">bêta-bloquants</span> antagonisent les récepteurs β-adrénergiques.</p>\n      <p><strong>Mécanisme.</strong> Effets <span class=\"kw-def\">inotrope, chronotrope, dromotrope et bathmotrope négatifs</span> (via β1) : anti-hypertenseur, anti-angineux, anti-arythmique de <span class=\"kw-chiffre\">classe II</span>, mais risque de <span class=\"kw-clinique\">poussée</span> d'IC et de trouble conductif. La libération du tonus α-vasoconstricteur explique le risque de spasme.</p>\n      <p><strong>Molécules.</strong> Cardiosélectifs β1 (acébutolol, <span class=\"kw-ttt\">aténolol</span>, <span class=\"kw-ttt\">bisoprolol</span>, <span class=\"kw-ttt\">métoprolol</span>, nébivolol) <span class=\"kw-bio\">vs</span> non cardiosélectifs (<span class=\"kw-ttt\">propranolol</span>, <span class=\"kw-ttt\">nadolol</span>, carvédilol, <span class=\"kw-ttt\">sotalol</span>, <span class=\"kw-ttt\">labétalol</span>). <strong>Ne pas confondre cardiosélectifs et <span class=\"kw-ttt\">bêta-bloquants</span> validés dans l'<span class=\"kw-def\">insuffisance cardiaque</span></strong> (<span class=\"kw-ttt\">bisoprolol, carvédilol, nébivolol, métoprolol</span>).</p>\n      <p><strong>Indications.</strong> <span class=\"kw-def\">Insuffisance cardiaque</span> à FEVG altérée, post-<span class=\"kw-def\">IDM</span>, <span class=\"kw-def\">SCA</span> et <span class=\"kw-clinique\">angor</span> stable (sauf <span class=\"kw-etio\">spasme coronaire</span>), troubles du rythme, FA permanente (contrôle de fréquence), traitement de fond de la <span class=\"kw-def\">migraine</span>, <span class=\"kw-def\">hyperthyroïdie</span>, tremblement essentiel, glaucome à angle ouvert, prévention de la <span class=\"kw-alerte\">rupture</span> de <span class=\"kw-clinique\">varices œsophagiennes</span>, <span class=\"kw-def\">HTA</span>.</p>\n      <p><strong><span class=\"kw-ci\">Contre-indications</span>.</strong> <span class=\"kw-ci\">Asthme</span> ++ ; BAV 2/3 non appareillés ; <span class=\"kw-ci\">bradycardie ou hypotension symptomatique</span> ; IC sévère décompensée ; <span class=\"kw-ci\">angor de Prinzmetal</span> ; <span class=\"kw-def\">syndrome de Raynaud</span> ; myasthénie. <span class=\"kw-ci\">CI relatives</span> : <span class=\"kw-clinique\">psoriasis</span>, <span class=\"kw-def\">BPCO</span>, AOMI.</p>\n      <p><strong>Effets indésirables.</strong> <span class=\"kw-clinique\">Asthénie</span>, <span class=\"kw-clinique\">bradycardie</span> sinusale, troubles de conduction, refroidissement des extrémités, aggravation d'une <span class=\"kw-def\">BPCO</span>/AOMI/d'un <span class=\"kw-clinique\">psoriasis</span>, insomnie et cauchemars, dysfonction érectile, <span class=\"kw-alerte\">masquage des signes d'hypoglycémie</span> chez le diabétique.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Dans l'<span class=\"kw-def\">HTA</span>, le <span class=\"kw-ttt\">bêta-bloquant</span> n'est utilisé à l'initiation que s'il existe une indication associée (<span class=\"kw-def\">insuffisance cardiaque</span>, coronaropathie, FA permanente, <span class=\"kw-ci\">grossesse</span>) — la monothérapie par bêta-bloquant n'est pas recommandée dans l'<span class=\"kw-def\">HTA</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-def\">HTA</span> · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":1},{"id":"330-4","rang":"A","rubrique":"Prise en charge","titre":"Médicaments du système rénine-angiotensine : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">médicaments du système rénine-angiotensine</span> regroupent les <span class=\"kw-ttt\">IEC</span> (« -pril ») et les <span class=\"kw-ttt\">ARA2</span> (« -<span class=\"kw-ttt\">sartan</span> »).</p>\n      <p><strong>Mécanisme.</strong> Diminution de l'effet de l'<span class=\"kw-def\">angiotensine 2</span> (inhibition de l'enzyme de conversion pour <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">IEC</span>, antagonisme du récepteur pour les <span class=\"kw-ttt\">ARA2</span>) : baisse de la vasoconstriction (↓ PA), baisse de l'aldostérone (↓ rétention hydrosodée, risque d'<span class=\"kw-alerte\">hyperkaliémie</span>), néphroprotection (↓ progression de la <span class=\"kw-bio\">microalbuminurie</span> et de l'<span class=\"kw-ci\">insuffisance rénale</span>).</p>\n      <p><strong>Indications.</strong> <span class=\"kw-def\">Insuffisance cardiaque</span> à FEVG diminuée (quelle que soit la NYHA), <span class=\"kw-def\">HTA</span>, post-<span class=\"kw-def\">IDM</span>, néphropathie diabétique, <span class=\"kw-def\">prévention secondaire</span> cardiovasculaire.</p>\n      <p><strong>Effets indésirables — moyen mnémotechnique CHARLOTTE.</strong></p>\n      <ul>\n        <li><strong>C</strong>éphalée</li>\n        <li><strong>H</strong>yperkaliémie (par diminution de l'aldostérone)</li>\n        <li><strong>A</strong>gueusie (surtout captopril)</li>\n        <li><strong>R</strong>énale : <span class=\"kw-ci\">insuffisance rénale</span> (rare si CI et <span class=\"kw-def\">surveillance</span> respectées)</li>\n        <li><strong>L</strong>eucopénie (neutropénie, agranulocytose — surtout captopril)</li>\n        <li><strong>O</strong>edème bradykinique (plus spécifique des <span class=\"kw-ttt\">IEC</span>, atteinte laryngée possible)</li>\n        <li><strong>T</strong>oux : <span class=\"kw-chiffre\">5-20 %</span> des <span class=\"kw-ttt\">IEC</span>, de <span class=\"kw-chiffre\">1 semaine</span> à<span class=\"kw-chiffre\"> 6 mois</span>, cesse en <span class=\"kw-chiffre\">4 jours</span> à l'arrêt (accumulation de bradykinine)</li>\n        <li><strong>T</strong>ension : <span class=\"kw-clinique\">hypotension</span>, surtout à la 1re dose</li>\n        <li><strong>É</strong>ruption cutanée</li>\n      </ul>\n      <p><strong><span class=\"kw-ci\">Contre-indications</span>.</strong> <span class=\"kw-ci\">Allergie</span> ; <span class=\"kw-ci\">ATCD d'angio-œdème</span> (contre-indique <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">IEC</span>, mais pas les <span class=\"kw-ttt\">ARA2</span>) ; <span class=\"kw-ci\">grossesse</span> ; <span class=\"kw-ci\">hyperkaliémie</span> ; sténose bilatérale des artères rénales.</p>\n      <p><strong>Interactions.</strong> Pas d'association <span class=\"kw-ttt\">IEC</span> + <span class=\"kw-ttt\">ARA2</span> ; <span class=\"kw-ttt\">lithium</span> ; <span class=\"kw-ttt\">AINS</span> (hyperkaliémie et IR) ; <span class=\"kw-ttt\">diurétiques</span> épargneurs de potassium et sels de potassium (hyperkaliémie).</p>\n      <p><strong><span class=\"kw-def\">Surveillance</span>.</strong> PA + <span class=\"kw-bio\">créatinine</span> + <span class=\"kw-bio\">ionogramme</span> (<span class=\"kw-bio\">kaliémie</span>, <span class=\"kw-bio\">natrémie</span>) : avant prescription, à <span class=\"kw-chiffre\">J7</span>-15, puis à chaque modification de posologie — <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">4 premières semaines</span> sont critiques. Une hausse de la <span class=\"kw-bio\">créatininémie</span> de <span class=\"kw-chiffre\">10-20 %</span> traduit l'efficacité du traitement ; une hausse <span class=\"kw-chiffre\">&gt; 30 %</span> impose l'arrêt temporaire et la recherche d'une sténose d'artère rénale ; une hyperkaliémie <span class=\"kw-chiffre\">&gt; 6 mmol/L</span> impose l'arrêt.</p>\n      <p><span class=\"kw-ttt\">ARA2</span> (« <span class=\"kw-ttt\">sartan</span> ») : indiqués en cas d'<span class=\"kw-ci\">intolérance</span> aux <span class=\"kw-ttt\">IEC</span> (moins de <span class=\"kw-clinique\">toux</span>), mêmes <span class=\"kw-ci\">contre-indications</span> sauf l'ATCD d'angio-<span class=\"kw-clinique\">œdème</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-def\">HTA</span> · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span></em></p>","frequence":3},{"id":"330-5","rang":"A","rubrique":"Prise en charge","titre":"Antagonistes des canaux calciques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">antagonistes des canaux calciques</span> (<span class=\"kw-ttt\">inhibiteurs calciques</span>) bloquent les canaux calciques voltage-dépendants, entraînant une vasodilatation.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Molécules</th><th>Action</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Dihydropyridines</strong> (« -dipine »)</td><td><span class=\"kw-ttt\">Amlodipine</span>, nicardipine, <span class=\"kw-ttt\">nifédipine</span>, lercanidipine</td><td>Action <span class=\"kw-def\">vasculaire</span> prédominante</td></tr>\n          <tr><td><strong>Bradycardisants</strong> (non dihydropyridines)</td><td><span class=\"kw-ttt\">Diltiazem</span>, <span class=\"kw-ttt\">vérapamil</span></td><td>Action mixte <span class=\"kw-def\">vasculaire + myocardique</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Effets indésirables.</strong> Dihydropyridines : <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">vertiges</span>, flush vasomoteur, <span class=\"kw-clinique\">œdèmes des membres inférieurs</span>, hypertrophie gingivale (<span class=\"kw-ttt\">nifédipine</span>). Bradycardisants : <span class=\"kw-clinique\">bradycardie</span> sinusale, troubles de conduction (BSA, BAV, BB).</p>\n      <p><strong><span class=\"kw-ci\">Contre-indications</span>.</strong> <span class=\"kw-ttt\">Inhibiteurs calciques</span> bradycardisants : <span class=\"kw-ci\">BAV 2 et 3</span>, <span class=\"kw-ci\">insuffisance cardiaque à FEVG altérée</span>.</p>\n      <p><strong>Indications.</strong> <span class=\"kw-def\">HTA</span>, notamment <span class=\"kw-clinique\">hypertension</span> systolique isolée ; <span class=\"kw-clinique\">angor</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-def\">HTA</span></em></p>","frequence":3},{"id":"330-6","rang":"A","rubrique":"Prise en charge","titre":"Anti-agrégants plaquettaires : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">anti-agrégants plaquettaires</span> inhibent l'activation et l'agrégation des <span class=\"kw-bio\">plaquettes</span>.</p>\n      <p><strong><span class=\"kw-ttt\">Aspirine</span>.</strong> Inhibition <strong>irréversible</strong> de la <span class=\"kw-def\">COX-1</span> → baisse du thromboxane A2 proagrégant. Effet anti-agrégant à dose <span class=\"kw-chiffre\">75-325 mg/j</span> (<span class=\"kw-chiffre\">300 mg</span> en dose d'attaque), <span class=\"kw-ttt\">antalgique</span> à partir de <span class=\"kw-chiffre\">500 mg</span>, anti-<span class=\"kw-etio\">inflammatoire</span> à partir de <span class=\"kw-chiffre\">1 g</span>. L'effet dure toute la vie de la <span class=\"kw-bio\">plaquette</span> (<span class=\"kw-chiffre\">7-10 jours</span>).</p>\n      <p><strong>Inhibiteurs de P2Y12.</strong> Bloquent le récepteur plaquettaire P2Y12 à l'ADP.</p>\n      <table >\n        <thead><tr><th>Molécule</th><th>Particularité</th><th>Dose charge / entretien</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Clopidogrel</span></td><td>Prodrogue activée par le <span class=\"kw-def\">CYP2C19</span> (<span class=\"kw-chiffre\">15-25 %</span> de mauvais métaboliseurs)</td><td><span class=\"kw-chiffre\">300-600 mg</span> / <span class=\"kw-chiffre\">75 mg ×1</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Prasugrel</span></td><td>Effet plus puissant ; <span class=\"kw-ci\">CI si ATCD d'AVC</span></td><td><span class=\"kw-chiffre\">60 mg</span> / <span class=\"kw-chiffre\">10 mg ×1</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Ticagrélor</span></td><td>Effet réversible ; <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">bradycardie</span>, hyperuricémie</td><td><span class=\"kw-chiffre\">180 mg</span> / <span class=\"kw-chiffre\">90 mg ×2</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Indications.</strong> <span class=\"kw-def\">Prévention secondaire</span> (coronaropathie, AOMI, <span class=\"kw-def\">AVC</span>) ; bithérapie <span class=\"kw-ttt\">aspirine</span> + inhibiteur de P2Y12 après un <span class=\"kw-def\">SCA</span> (durée <span class=\"kw-chiffre\">1-12 mois</span> selon le risque <span class=\"kw-etio\">hémorragique</span>).</p>\n      <p><strong><span class=\"kw-ci\">Contre-indications</span>.</strong> <span class=\"kw-ci\">Ulcère gastro-duodénal évolutif</span>, <span class=\"kw-alerte\">hémorragie active</span>, <span class=\"kw-ci\">insuffisance hépatique</span> sévère, <span class=\"kw-ci\">hypersensibilité</span>. <span class=\"kw-ci\">CI relatives</span> du <span class=\"kw-ttt\">prasugrel</span> : poids &lt;<span class=\"kw-chiffre\"> 60 kg</span>, âge &gt;<span class=\"kw-chiffre\"> 75 ans</span>.</p>\n      <p><strong>Effets indésirables et <span class=\"kw-def\">surveillance</span>.</strong> Risque <span class=\"kw-etio\">hémorragique</span> ; réactions d'<span class=\"kw-ci\">hypersensibilité</span> ; pas de test <span class=\"kw-ttt\">biologique</span> fiable de routine pour l'efficacité ; surveillance clinique + <span class=\"kw-bio\">NFS</span> annuelle.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Gestion péri-opératoire — <strong>règle des 3-5-7</strong> : arrêt <span class=\"kw-chiffre\">3 jours</span> avant le geste pour l'<span class=\"kw-ttt\">aspirine</span>, <span class=\"kw-chiffre\">5 jours</span> pour <span class=\"kw-ttt\">clopidogrel</span> et ticagrélor, <span class=\"kw-chiffre\">7 jours</span> pour le <span class=\"kw-ttt\">prasugrel</span>. L'<span class=\"kw-ttt\">aspirine</span> est maintenue chaque fois que possible ; un acte invasif est différé après pose de <span class=\"kw-ttt\">stent</span> (stent nu <span class=\"kw-chiffre\">≥ 6 semaines</span>, stent actif <span class=\"kw-chiffre\">3-6 mois</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-def\">AVC</span></em></p>","frequence":1},{"id":"330-7","rang":"A","rubrique":"Prise en charge","titre":"Héparines : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">héparines</span> sont des <span class=\"kw-ttt\">anticoagulants</span> injectables d'action rapide.</p>\n      <p><strong>Mécanisme.</strong> Potentialisation de l'<span class=\"kw-def\">antithrombine</span> : <span class=\"kw-clinique\">les</span> chaînes longues inactivent à la fois le <span class=\"kw-def\">FIIa (thrombine)</span> et le <span class=\"kw-def\">FXa</span> ; les chaînes courtes inactivent surtout le FXa.</p>\n      <table >\n        <thead><tr><th>—</th><th><span class=\"kw-ttt\">HNF</span></th><th><span class=\"kw-ttt\">HBPM</span></th><th>Fondaparinux</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Voie / molécules</strong></td><td>IV (sodique) ou SC (calcique)</td><td>SC — <span class=\"kw-ttt\">énoxaparine</span>, tinzaparine, nadroparine, daltéparine</td><td>SC — <span class=\"kw-ttt\">fondaparinux</span></td></tr>\n          <tr><td><strong>Action</strong></td><td>Anti-IIa + anti-Xa</td><td>Anti-Xa prédominante</td><td>Anti-Xa exclusive</td></tr>\n          <tr><td><strong>Élimination rénale</strong></td><td>Faible — <strong>seule utilisable si IR sévère</strong></td><td>Rénale — <span class=\"kw-ci\">CI si ClCr &lt; 30 mL/min</span></td><td>Rénale — <span class=\"kw-ci\">CI si ClCr &lt; 30 mL/min</span></td></tr>\n          <tr><td><strong>Antidote</strong></td><td><span class=\"kw-ttt\">Sulfate de protamine</span></td><td>Partiel</td><td>Aucun établi</td></tr>\n          <tr><td><strong>Risque de TIH</strong></td><td>Possible</td><td>Rare</td><td>Nul</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Indications.</strong> Situations urgentes : <span class=\"kw-def\">TVP</span>, EP, <span class=\"kw-def\">SCA</span>, troubles du rythme nécessitant une <span class=\"kw-ttt\">anticoagulation</span> ; <span class=\"kw-ttt\">HBPM</span> largement utilisée en prophylaxie de la maladie thromboembolique veineuse.</p>\n      <p><strong><span class=\"kw-def\">Surveillance</span>.</strong> Efficacité de l'<span class=\"kw-ttt\">HNF</span> par <span class=\"kw-bio\">TCA</span> (2-3× le témoin) ou activité anti-Xa : son effet est imprévisible, surveillance quotidienne. <span class=\"kw-ttt\">HBPM</span> : en général pas de surveillance d'efficacité, sauf poids extrême, IR modérée ou risque <span class=\"kw-etio\">hémorragique</span>. <strong>Surveillance de la <span class=\"kw-bio\">numération plaquettaire</span> (risque de TIH)</strong> : systématique sous <span class=\"kw-ttt\">HNF</span>, non systématique sous HBPM.</p>\n      <p><strong>Effets indésirables et <span class=\"kw-ci\">contre-indications</span>.</strong> Hémorragie ; <span class=\"kw-alerte\">thrombopénie induite par l'héparine (TIH)</span> ; hyperkaliémie (hypoaldostéronisme) ; <span class=\"kw-def\">ostéoporose</span> ; <span class=\"kw-clinique\">nécrose</span> cutanée au point d'injection. <span class=\"kw-ci\">CI</span> : <span class=\"kw-def\">endocardite</span> aiguë <span class=\"kw-etio\">bactérienne</span>, anesthésie péridurale/rachianesthésie, saignement actif, ATCD de TIH.</p>\n      <p><strong>TIH de type 2</strong> — complication la plus sévère :</p>\n      <table >\n        <thead><tr><th>—</th><th>TIH type 1</th><th>TIH type 2</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Mécanisme</strong></td><td>Non immunologique</td><td><span class=\"kw-def\">Immuno-allergique</span> (Ac anti-PF4)</td></tr>\n          <tr><td><strong>Survenue</strong></td><td>Précoce (&lt;<span class=\"kw-chiffre\"> 5 jours</span>)</td><td>Retardée (<span class=\"kw-chiffre\">J5-J21</span>)</td></tr>\n          <tr><td><strong>Thrombopénie</strong></td><td>Modérée (&gt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>100</span> G/L</span>)</td><td>&lt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>100</span> G/L</span> ou chute &gt;<span class=\"kw-chiffre\"> 50 %</span></td></tr>\n          <tr><td><strong>Gravité</strong></td><td>Bénigne, régresse</td><td><span class=\"kw-alerte\">Risque thrombotique +++ (50 %)</span> ; fatale dans <span class=\"kw-chiffre\">30 %</span> des cas</td></tr>\n        </tbody>\n      </table>\n      <p>Diagnostic : <span class=\"kw-def\">score</span> 4T, recherche d'<span class=\"kw-bio\">Ac anti-PF4</span>, tests d'activation plaquettaire. Prise en charge : arrêt de toute source d'<span class=\"kw-ttt\">héparine</span>, relais par <span class=\"kw-ttt\">danaparoïde</span> ou argatroban, déclaration à la pharmacovigilance.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Devant une thrombopénie ou une chute &gt;<span class=\"kw-chiffre\"> 50 %</span> des <span class=\"kw-bio\">plaquettes</span> entre J5 et <span class=\"kw-chiffre\">J21</span> sous <span class=\"kw-ttt\">héparine</span>, évoquer une <span class=\"kw-alerte\">TIH de type 2</span> : arrêt immédiat de l'<span class=\"kw-ttt\">héparine</span>. La <span class=\"kw-alerte\">transfusion de plaquettes est contre-indiquée</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 232 — <span class=\"kw-def\">Fibrillation atriale</span></em></p>","frequence":5},{"id":"330-8","rang":"A","rubrique":"Prise en charge","titre":"Anticoagulants oraux (anti-vitamine K (AVK) et anticoagulants oraux directs (AOD)) : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">anticoagulants oraux</span> comprennent les <span class=\"kw-ttt\">AVK</span> et les <span class=\"kw-ttt\">AOD</span>.</p>\n      <p><strong>A — Antivitamines K (<span class=\"kw-ttt\">AVK</span>).</strong> Mécanisme : blocage hépatique de la synthèse des facteurs vitamine-K dépendants (<span class=\"kw-def\">II, VII, IX, X</span> + protéines C et S). Molécules : <span class=\"kw-ttt\">warfarine</span> (Coumadine, référence), <span class=\"kw-ttt\">fluindione</span> (l'ANSM recommande de ne plus l'instaurer en 1re intention — atteinte rénale immuno-<span class=\"kw-etio\">allergique</span>), acénocoumarol. Délai d'action long (<span class=\"kw-chiffre\">3-5 jours</span>).</p>\n      <p><span class=\"kw-def\">Surveillance</span> par l'<span class=\"kw-bio\">INR</span> : cible <span class=\"kw-chiffre\">2-3</span> dans la plupart des indications, <span class=\"kw-chiffre\">3-4,5</span> pour <span class=\"kw-clinique\">les</span> prothèses valvulaires mécaniques. Rythme : 2×/semaine les deux premières semaines, puis espacement, <span class=\"kw-chiffre\">≥ 1×/mois</span> au long cours. Le 1er contrôle à<span class=\"kw-chiffre\"> 48-72 h</span> ne doit pas déjà atteindre la cible (risque de surdosage). Relais <span class=\"kw-ttt\">héparine</span>-AVK : chevauchement <span class=\"kw-chiffre\">≥ 4-5 jours</span> + <span class=\"kw-chiffre\">2 INR</span> efficaces à<span class=\"kw-chiffre\"> 24 h</span> d'intervalle. Pas de régime particulier (alimentation équilibrée, même légumes verts).</p>\n      <p><span class=\"kw-ci\">Contre-indications</span> des <span class=\"kw-ttt\">AVK</span> : <span class=\"kw-ci\">grossesse</span> (tératogènes au 1er trimestre, hémorragiques au 3e), insuffisance hépatique sévère, FA non valvulaire (privilégier <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AOD</span>). Indications préférentielles résiduelles : <strong>porteur de valve mécanique, <span class=\"kw-ci\">insuffisance rénale</span> sévère, SAPL</strong>.</p>\n      <p><strong>B — <span class=\"kw-ttt\">Anticoagulants</span> oraux directs (<span class=\"kw-ttt\">AOD</span>).</strong> Mécanisme : inhibition directe et réversible du <span class=\"kw-def\">FIIa</span> (<span class=\"kw-ttt\">dabigatran</span>) ou du <span class=\"kw-def\">FXa</span> (<span class=\"kw-ttt\">rivaroxaban</span>, <span class=\"kw-ttt\">apixaban</span>). Élimination rénale (<span class=\"kw-ttt\">dabigatran</span> <span class=\"kw-chiffre\">80 %</span>, <span class=\"kw-ttt\">rivaroxaban</span> <span class=\"kw-chiffre\">33 %</span>, <span class=\"kw-ttt\">apixaban</span> <span class=\"kw-chiffre\">25 %</span>) → évaluation de la fonction rénale obl<span class=\"kw-chiffre\">iga</span>toire. Avantages sur <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AVK</span> : action rapide, pas de <span class=\"kw-def\">surveillance</span> <span class=\"kw-ttt\">biologique</span> de routine, moins d'hémorragies intracrâniennes. <span class=\"kw-ci\">Contre-indications</span> : <strong>valve mécanique et rétrécissement mitral serré (<span class=\"kw-ci\">CI absolue</span>)</strong>, <span class=\"kw-ci\">insuffisance rénale</span> sévère, atteinte hépatique Child B-C, grossesse, interactions majeures (inducteurs/inhibiteurs du CYP3A4 et de la P-glycoprotéine). Antidotes : <span class=\"kw-ttt\">idarucizumab</span> (<span class=\"kw-ttt\">dabigatran</span>), <span class=\"kw-ttt\">andexanet alfa</span> ou PPSB (anti-Xa). Jamais de chevauchement entre un <span class=\"kw-ttt\">anticoagulant</span> injectable et un <span class=\"kw-ttt\">AOD</span>.</p>\n      <p><strong>Accidents hémorragiques.</strong> Critères d'hémorragie grave : hémorragie non contrôlable, instabilité hémodynamique, geste hémostatique nécessaire, transfusion nécessaire, localisation menaçant le <span class=\"kw-alerte\">pronostic vital</span> ou fonctionnel. Surdosage asymptomatique en <span class=\"kw-ttt\">AVK</span> : <span class=\"kw-bio\">INR</span> <span class=\"kw-chiffre\">4-6</span> → saut de prise ; <span class=\"kw-bio\">INR</span> <span class=\"kw-chiffre\">6-10</span> → arrêt + <span class=\"kw-ttt\">vitamine K</span><span class=\"kw-chiffre\"> 1-2 mg</span> PO ; <span class=\"kw-bio\">INR</span> <span class=\"kw-chiffre\">&gt; 10</span> → arrêt + vitamine K <span class=\"kw-chiffre\">5 mg</span> PO. Tout accident des <span class=\"kw-ttt\">anticoagulants</span> doit être déclaré à la pharmacovigilance.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/330/hematome-psoas-tdm.png\" alt=\"TDM abdomino-pelvienne montrant une hyperdensité spontanée du psoas gauche, hématome du psoas\" loading=\"lazy\">\n        <figcaption>Hématome du psoas gauche : hyperdensité spontanée à la <span class=\"kw-imagerie\">TDM</span> abdomino-pelvienne. Source : fiches sources EDN item 330.</figcaption>\n      </figure>\n      <p>L'<span class=\"kw-alerte\">hématome du psoas</span> est une complication <span class=\"kw-etio\">hémorragique</span> des <span class=\"kw-ttt\">anticoagulants</span> : <span class=\"kw-clinique\">psoïtis</span> (cuisse fléchie en position <span class=\"kw-ttt\">antalgique</span>), cruralgie sans lombalgie, <span class=\"kw-clinique\">déglobulisation sans saignement extériorisé</span>. Diagnostic par <span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">TDM</span> ; prise en charge selon le volume et l'<span class=\"kw-bio\">INR</span> (antagonisation, voire embolisation radiologique si volumineux).</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> En cas d'hémorragie grave sous <span class=\"kw-ttt\">AVK</span>, il ne suffit pas d'arrêter l'<span class=\"kw-ttt\">AVK</span> : il faut l'<strong>antagoniser</strong> (<span class=\"kw-ttt\">PPSB</span> + <span class=\"kw-ttt\">vitamine K</span>, objectif <span class=\"kw-chiffre\">INR &lt; 1,5</span>), même si l'<span class=\"kw-bio\">INR</span> est dans la cible de l'indication.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 232 — <span class=\"kw-def\">Fibrillation atriale</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":5},{"id":"330-9","rang":"A","rubrique":"Prise en charge","titre":"Benzodiazépines : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<div class=\"callout callout-warn\"><strong>À compléter.</strong> Aucun contenu correspondant à cet objectif n'a été trouvé dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>330-therapeutique-classe-mdc/</code>. Kevin enrichira ce paragraphe (Notion, Collège de pharmacologie / psychiatrie, ou recherche ciblée) — mécanismes d'action, indications, effets secondaires, interactions médicamenteuses, modalités de <span class=\"kw-def\">surveillance</span> et causes d'échec des <span class=\"kw-ttt\">benzodiazépines</span>.</div>","frequence":0},{"id":"330-10","rang":"A","rubrique":"Prise en charge","titre":"Inhibiteurs spécifiques de recapture de la sérotonine : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<div class=\"callout callout-warn\"><strong>À compléter.</strong> Aucun contenu correspondant à cet objectif n'a été trouvé dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>330-therapeutique-classe-mdc/</code>. Kevin enrichira ce paragraphe (Notion, Collège de pharmacologie / psychiatrie, ou recherche ciblée) — mécanismes d'action, indications, effets secondaires, interactions médicamenteuses, modalités de <span class=\"kw-def\">surveillance</span> et causes d'échec des <span class=\"kw-ttt\">inhibiteurs spécifiques de recapture de la sérotonine</span>.</div>","frequence":0},{"id":"330-11","rang":"A","rubrique":"Prise en charge","titre":"Antipsychotiques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<div class=\"callout callout-warn\"><strong>À compléter.</strong> Aucun contenu correspondant à cet objectif n'a été trouvé dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>330-therapeutique-classe-mdc/</code>. Kevin enrichira ce paragraphe (Notion, Collège de pharmacologie / psychiatrie, ou recherche ciblée) — mécanismes d'action, indications, effets secondaires, interactions médicamenteuses, modalités de <span class=\"kw-def\">surveillance</span> et causes d'échec des <span class=\"kw-ttt\">antipsychotiques</span>.</div>","frequence":0},{"id":"330-12","rang":"A","rubrique":"Prise en charge","titre":"Antiépileptiques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<div class=\"callout callout-warn\"><strong>À compléter.</strong> Aucun contenu correspondant à cet objectif n'a été trouvé dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>330-therapeutique-classe-mdc/</code>. Kevin enrichira ce paragraphe (Notion, Collège de pharmacologie / neurologie, ou recherche ciblée) — mécanismes d'action, indications, effets secondaires, interactions médicamenteuses, modalités de <span class=\"kw-def\">surveillance</span> et causes d'échec des <span class=\"kw-ttt\">antiépileptiques</span>.</div>","frequence":0},{"id":"330-13","rang":"A","rubrique":"Prise en charge","titre":"Hypolipémiants : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">hypolipémiants</span> visent à réduire le <span class=\"kw-bio\">LDL</span>-cholestérol et/ou les <span class=\"kw-bio\">triglycérides</span>.</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Mécanisme</th><th>Effet lipidique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Statines</span></td><td>Inhibition de l'<span class=\"kw-def\">HMG-CoA réductase</span> → ↓ synthèse de <span class=\"kw-bio\">cholestérol</span> + ↑ récepteurs <span class=\"kw-bio\">LDL</span></td><td>↓ LDLc <span class=\"kw-chiffre\">25-45 %</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Ézétimibe</span></td><td>↓ absorption intestinale du <span class=\"kw-bio\">cholestérol</span></td><td>↓ LDLc <span class=\"kw-chiffre\">20 %</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Colestyramine</span> (résine)</td><td>↓ réabsorption des sels biliaires</td><td>↓ LDLc <span class=\"kw-chiffre\">20 %</span> ; ↑ TG</td></tr>\n          <tr><td><span class=\"kw-ttt\">Fibrates</span></td><td>Activation des PPARα</td><td>↓ TG <span class=\"kw-chiffre\">20-40 %</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Oméga-3</span></td><td>↓ production de VLDL</td><td>↓ TG <span class=\"kw-chiffre\">10-30 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ttt\">Statines</span>.</strong> Effets indésirables : <span class=\"kw-clinique\">myalgies</span> (le plus fréquent), élévation des <span class=\"kw-bio\">CPK</span> (rhabdomyolyse rare), élévation des <span class=\"kw-bio\">transaminases</span> (<span class=\"kw-def\">hépatite</span> rare), surrisque de <span class=\"kw-def\">DT2</span> (RR 1,1). <span class=\"kw-ci\">CI</span> : <span class=\"kw-ci\">grossesse</span>, allaitement, <span class=\"kw-ci\">hypersensibilité</span>. Inhibiteurs de la <span class=\"kw-def\">PCSK9</span> (alirocumab, évolocumab) : immunoglobulines monoclonales SC, indications limitées (<span class=\"kw-etio\">hypercholestérolémie</span> familiale, décours d'un <span class=\"kw-def\">SCA</span> si <span class=\"kw-bio\">LDL</span> non contrôlé).</p>\n      <p><strong>Interactions.</strong> <span class=\"kw-ttt\">Statines</span> métabolisées par le CYP3A4 (sauf <span class=\"kw-ttt\">pravastatine</span> et <span class=\"kw-ttt\">rosuvastatine</span>) ; <strong><span class=\"kw-ci\">association statine + gemfibrozil contre-indiquée</span></strong> ; <span class=\"kw-ttt\">statine</span>/ézétimibe/fibrate augmentent l'effet des <span class=\"kw-ttt\">AVK</span> ; le pamplemousse majore <span class=\"kw-clinique\">les</span> effets de la <span class=\"kw-ttt\">simvastatine</span> ; la colestyramine diminue l'absorption des autres médicaments (à prendre 1h30 avant ou <span class=\"kw-chiffre\">3h</span> après).</p>\n      <p><strong><span class=\"kw-def\">Surveillance</span>.</strong> <span class=\"kw-bio\">Bilan lipidique</span> : toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">4-6 semaines</span> en <span class=\"kw-def\">prévention secondaire</span>. <span class=\"kw-bio\">Surveillance musculaire</span> essentiellement clinique : dosage des <span class=\"kw-bio\">CPK</span> seulement si symptômes (CAT si <span class=\"kw-bio\">CPK</span> <span class=\"kw-chiffre\">&gt; 5 N</span> : arrêt). <span class=\"kw-bio\">Surveillance hépatique</span> : <span class=\"kw-bio\">ALAT</span> avant traitement, à<span class=\"kw-chiffre\"> 8 semaines</span>, puis 1×/an (CAT si <span class=\"kw-bio\">ALAT</span> <span class=\"kw-chiffre\">≥ 3 N</span> : arrêt ou <span class=\"kw-ttt\">réduction</span> de posologie).</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le dosage systématique des <span class=\"kw-bio\">CPK</span> n'est pas recommandé en l'absence de symptôme musculaire. L'association <span class=\"kw-ci\">statine + gemfibrozil</span> est <span class=\"kw-ci\">contre-indiquée</span> (risque de rhabdomyolyse).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 222 — FDR cardiovasculaire</em></p>","frequence":2},{"id":"330-14","rang":"A","rubrique":"Prise en charge","titre":"Insulines et analogues de l’insuline : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<div class=\"callout callout-warn\"><strong>À compléter.</strong> Le dossier <code>330-therapeutique-classe-mdc/</code> ne contient pas de fiche dédiée à l'<span class=\"kw-ttt\">insulinothérapie</span> (la fiche « Anti-diabétiques » ne traite que <span class=\"kw-clinique\">les</span> antidiabétiques non insuliniques). Kevin enrichira ce paragraphe (Collège d'endocrinologie, item 247) — mécanismes d'action, types d'<span class=\"kw-ttt\">insulines et analogues</span>, schémas, indications, effets secondaires, modalités de <span class=\"kw-def\">surveillance</span> et causes d'échec.</div>","frequence":0},{"id":"330-15","rang":"A","rubrique":"Prise en charge","titre":"Antidiabétiques (metformine, sulfonulurées, inhibiteurs de la DPP4, agonistes du GLP1, inhibiteurs des SGLT2) : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">antidiabétiques</span> non insuliniques regroupent plusieurs classes orales et injectables, utilisées dans le <span class=\"kw-def\"><span class=\"kw-def\">diabète</span> de type 2</span>.</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Mécanisme</th><th>Poids / hypoglycémie</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Metformine</span> (biguanide)</td><td>↓ insulinorésistance hépatique</td><td>Neutre ; pas d'hypoglycémie</td><td><strong>1re intention</strong> ; EI digestifs ; <span class=\"kw-alerte\">acidose lactique</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Sulfamides</span> hypoglycémiants</td><td>↑ insulinosécrétion</td><td>Prise de poids ; <span class=\"kw-alerte\">hypoglycémie</span></td><td><span class=\"kw-ci\">Allergie</span> aux <span class=\"kw-ttt\">sulfamides</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Glinides</span> (répaglinide)</td><td>↑ insulinosécrétion</td><td>Prise de poids ; hypoglycémie (moindre)</td><td>Couvre le repas ; utilisable si IR</td></tr>\n          <tr><td><span class=\"kw-ttt\">iDPP4</span> (« -<span class=\"kw-ttt\">gliptine</span> »)</td><td>Inhibent la dégradation du <span class=\"kw-ttt\">GLP-1</span></td><td>Neutre ; pas d'hypoglycémie</td><td>Utilisable chez le sujet âgé</td></tr>\n          <tr><td><span class=\"kw-ttt\">iSGLT2</span> (« -gliflozine »)</td><td>↓ réabsorption tubulaire du glucose</td><td><span class=\"kw-clinique\">Perte de poids</span> ; pas d'hypoglycémie</td><td>Protection cardiorénale ; <span class=\"kw-alerte\">acidocétose euglycémique</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Agonistes du GLP-1</span></td><td>↑ insulinosécrétion glucose-dépendante, ↓ vidange gastrique</td><td><span class=\"kw-clinique\">Perte de poids</span> ; pas d'hypoglycémie</td><td>Voie SC ; bénéfice cardiovasculaire ; EI digestifs</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ttt\">Metformine</span>.</strong> Médicament de 1re intention en l'absence de <span class=\"kw-ci\">contre-indication</span> ; <span class=\"kw-ci\">CI</span> : <span class=\"kw-ci\">insuffisance rénale</span> sévère (&lt;<span class=\"kw-chiffre\"> 30 mL</span>/min), <span class=\"kw-ci\">insuffisance hépatique</span>, hypoxie tissulaire, pathologie aiguë. Pas de risque d'hypoglycémie sauf prise d'<span class=\"kw-etio\">alcool</span>. <strong>Pas de toxicité rénale</strong>, mais élimination rénale → demi-dose au <span class=\"kw-def\">stade</span> 3A d'insuffisance rénale.</p>\n      <p><strong><span class=\"kw-ttt\">iSGLT2</span>.</strong> Effets indésirables à connaître : infections génitales pouvant aller jusqu'à la <span class=\"kw-alerte\">gangrène de Fournier</span>, <span class=\"kw-alerte\">acidocétose euglycémique</span>, <span class=\"kw-clinique\">déshydratation</span>. <strong>Agonistes du <span class=\"kw-ttt\">GLP-1</span></strong> : <span class=\"kw-ci\">CI</span> gastroparésie, ATCD de pancréatopathie.</p>\n      <p><strong>Adaptation à l'<span class=\"kw-ci\">insuffisance rénale</span>.</strong> <span class=\"kw-bio\">DFG</span> <span class=\"kw-chiffre\">&gt; 60 mL/min</span> : tous utilisables. <span class=\"kw-def\">Stade</span> 3A : adapter <span class=\"kw-clinique\">les</span> posologies (<span class=\"kw-ttt\">metformine</span> à demi-dose). <span class=\"kw-chiffre\">Stade 4</span>-5 (<span class=\"kw-chiffre\">&lt; 30 mL/min</span>) : seules classes autorisées = <span class=\"kw-ttt\">insuline</span>, répaglinide, inhibiteurs de l'α-glucosidase, iDPP4 à posologie adaptée. <span class=\"kw-def\">Surveillance</span> de l'<span class=\"kw-bio\">HbA1c</span>, moins fiable en cas d'<span class=\"kw-def\">IRC</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-def\">Diabète</span> · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span></em></p>","frequence":2},{"id":"330-16","rang":"A","rubrique":"Prise en charge","titre":"Antalgiques non opioïdes (dont paracétamol) : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">antalgiques non opioïdes</span> constituent le <span class=\"kw-def\">palier 1</span> de l'OMS : <span class=\"kw-ttt\">paracétamol</span>, <span class=\"kw-ttt\">AINS</span> et <span class=\"kw-ttt\">néfopam</span>.</p>\n      <p><strong><span class=\"kw-ttt\">Paracétamol</span>.</strong> Mécanisme mal connu : action centrale non morphinique (variante COX-3 du SNC), <strong>sans effet anti-<span class=\"kw-etio\">inflammatoire</span></strong>. <span class=\"kw-ttt\">Antalgique</span> de 1re intention dans la douleur aiguë et chronique (bon rapport efficacité/tolérance). Posologie : adulte <span class=\"kw-chiffre\">3-4 g/j</span> (réduite à <span class=\"kw-chiffre\">3 g/j</span> chez le sujet âgé, éthylique, dénutri ou insuffisant rénal), intervalle <span class=\"kw-chiffre\">4-6 h</span> ; enfant <span class=\"kw-chiffre\">60 mg/kg/j</span> (AMM dès la naissance per os et IV — voie rectale non recommandée). Délai d'action ~<span class=\"kw-chiffre\">1 h</span>, durée <span class=\"kw-chiffre\">4-6 h</span>.</p>\n      <p><strong>Hépatotoxicité.</strong> Le surdosage entraîne une <span class=\"kw-alerte\">nécrose hépatique centro-lobulaire</span> ; dose <span class=\"kw-etio\">toxique</span> à partir de <span class=\"kw-chiffre\">100-150 mg/kg</span> ou <span class=\"kw-chiffre\">10 g</span> en une prise ; antidote <span class=\"kw-ttt\">N-acétylcystéine</span>, idéalement dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">8 h</span>. <span class=\"kw-ci\">CI</span> : <span class=\"kw-alerte\">insuffisance hépatocellulaire</span>, <span class=\"kw-ci\">allergie</span>.</p>\n      <p><strong>Néfopam (Acupan).</strong> <span class=\"kw-ttt\">Antalgique</span> central non morphinique, <strong>sans effet anti-<span class=\"kw-etio\">inflammatoire</span> ni antipyrétique</strong>, réservé au milieu hospitalier (voies injectables IM/IV seules). Effets indésirables atropiniques : <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">sueurs</span>, mydriase, <span class=\"kw-alerte\">rétention aiguë d'urine, confusion, convulsions</span>. À la différence des morphiniques, il <strong>ne provoque pas de <span class=\"kw-def\">dépression</span> respiratoire ni de ralentissement du transit</strong>. <span class=\"kw-ci\">CI</span> : <span class=\"kw-ci\">grossesse</span>, enfant &lt;<span class=\"kw-chiffre\"> 15 ans</span>, <span class=\"kw-def\">épilepsie</span>/<span class=\"kw-clinique\">convulsions</span>, glaucome à angle fermé, adénome prostatique.</p>\n      <p><strong>Place dans la stratégie.</strong> Paliers OMS : palier 1 si EVA <span class=\"kw-chiffre\">1-3</span> ; palier 2 ou <span class=\"kw-ttt\">néfopam</span> si EVA <span class=\"kw-chiffre\">4-6</span> ; titration morphinique si EVA <span class=\"kw-chiffre\">≥ 6-7</span>. Objectif : EVA/EN &lt; 3, avec <span class=\"kw-def\">réévaluation</span> régulière. <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">AINS</span>, également <span class=\"kw-ttt\">antalgiques</span> de palier 1, sont détaillés dans l'objectif consacré aux <span class=\"kw-ttt\">AINS</span> et <span class=\"kw-ttt\">corticoïdes</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 135 — <span class=\"kw-ttt\">Antalgique</span></em></p>","frequence":3},{"id":"330-17","rang":"A","rubrique":"Prise en charge","titre":"Antalgiques opioïdes : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">antalgiques opioïdes</span> agissent sur les récepteurs <span class=\"kw-ttt\">opioïdes</span> (surtout le récepteur <span class=\"kw-def\">µ</span>). On distingue les <span class=\"kw-ttt\">opioïdes</span> faibles (palier 2) et forts (palier 3).</p>\n      <p><strong>A — Opioïdes faibles (palier 2).</strong> <span class=\"kw-ttt\">Codéine</span>, <span class=\"kw-ttt\">tramadol</span>, poudre d'opium ; faible affinité pour <span class=\"kw-clinique\">les</span> récepteurs <span class=\"kw-ttt\">opioïdes</span>.</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Codéine</span> : prodrogue métabolisée par le <span class=\"kw-def\">CYP2D6</span> en <span class=\"kw-ttt\">morphine</span> (~<span class=\"kw-chiffre\">10 %</span>). Variabilité <span class=\"kw-etio\">génétique</span> — métaboliseurs lents (inefficacité) ou ultra-rapides (<span class=\"kw-ci\">hypersensibilité</span>). <span class=\"kw-ci\">CI &lt; 12 ans</span> ; jamais après amygdalectomie ou adénoïdectomie.</li>\n        <li><span class=\"kw-ttt\">Tramadol</span> : action mixte, opioïde µ + monoaminergique (inhibition de recapture <span class=\"kw-ttt\">noradrénaline</span>/sérotonine). <span class=\"kw-ci\">CI &lt; 3 ans</span>, <span class=\"kw-def\">épilepsie</span> non contrôlée, association aux <span class=\"kw-ttt\">IMAO</span>. Risque de <span class=\"kw-alerte\">syndrome sérotoninergique</span> et de <span class=\"kw-clinique\">convulsions</span>. Dose maximale <span class=\"kw-chiffre\">400 mg/j</span> per os ; prescription limitée à<span class=\"kw-chiffre\"> 3 mois</span>.</li>\n      </ul>\n      <p><strong>B — Opioïdes forts (palier 3).</strong> <span class=\"kw-ttt\">Morphine</span> (référence), <span class=\"kw-ttt\">oxycodone</span>, hydromorphone, <span class=\"kw-ttt\">fentanyl</span>, méthadone. Classement en <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>roupes :</p>\n      <table >\n        <thead><tr><th>Groupe</th><th>Molécules</th><th>Particularité</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Agonistes purs</strong></td><td><span class=\"kw-ttt\">Morphine, oxycodone, hydromorphone, fentanyl, méthadone</span></td><td><strong>Pas d'effet plafond</strong>, pas de posologie maximale</td></tr>\n          <tr><td><strong>Agoniste partiel</strong></td><td><span class=\"kw-ttt\">Buprénorphine</span></td><td>Effet plafond</td></tr>\n          <tr><td><strong>Agoniste-antagoniste</strong></td><td><span class=\"kw-ttt\">Nalbuphine</span></td><td><span class=\"kw-ci\">Association aux agonistes purs contre-indiquée</span></td></tr>\n          <tr><td><strong>Antagoniste</strong></td><td><span class=\"kw-ttt\">Naloxone</span></td><td>Traitement du surdosage</td></tr>\n        </tbody>\n      </table>\n      <p>AMM : seuls <span class=\"kw-ttt\">morphine, oxycodone et fentanyl transdermique</span> ont une AMM dans <span class=\"kw-clinique\">les</span> douleurs <strong>non cancéreuses</strong>. Le <strong><span class=\"kw-ttt\">fentanyl</span> transmuqueux</strong> est réservé aux accès douloureux paroxystiques d'un patient cancéreux ayant déjà un traitement de fond <span class=\"kw-chiffre\">≥ 60 mg/j de morphine depuis ≥ 7 jours</span> — jamais en initiation.</p>\n      <p><strong>Effets indésirables.</strong></p>\n      <table >\n        <thead><tr><th>Effet</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Constipation</span></td><td>Quasi systématique, <strong>pas de phénomène de tolérance</strong> → laxatif systématiquement coprescrit</td></tr>\n          <tr><td><span class=\"kw-clinique\">Nausées</span>, <span class=\"kw-clinique\">vomissements</span></td><td>Fréquents, s'estompent en <span class=\"kw-chiffre\">2-3 semaines</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Dépression respiratoire</span></td><td>FR &lt;<span class=\"kw-chiffre\"> 10/min</span> — signe de surdosage</td></tr>\n          <tr><td>Myosis, sédation, RAU, <span class=\"kw-clinique\">prurit</span></td><td>Myosis serré dose-dépendant</td></tr>\n          <tr><td><span class=\"kw-alerte\">Hyperalgésie</span></td><td>Sensibilisation paradoxale à la douleur sous <span class=\"kw-ttt\">opioïdes</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ci\">Contre-indications</span>.</strong> <span class=\"kw-ci\">Insuffisance respiratoire décompensée</span>, <span class=\"kw-alerte\">insuffisance hépatocellulaire</span> sévère, <span class=\"kw-ci\">insuffisance rénale</span> sévère (ClCr &lt;<span class=\"kw-chiffre\"> 15 mL</span>/min), <span class=\"kw-def\">épilepsie</span> non contrôlée, traumatisme crânien / <span class=\"kw-alerte\">HTIC</span>, intoxication alcoolique aiguë, association aux <span class=\"kw-ttt\">IMAO</span> ou à un agoniste-antagoniste.</p>\n      <p><strong><span class=\"kw-def\">Surveillance</span> et causes d'échec.</strong> Toujours associer un <span class=\"kw-ttt\">antalgique</span> de palier 1 ; <span class=\"kw-ci\">ne jamais</span> associer 2 morphiniques ; prudence avec <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">benzodiazépines</span> (<span class=\"kw-def\">dépression</span> respiratoire) ; ne pas dépasser <span class=\"kw-chiffre\">150 mg</span>/j d'équivalent <span class=\"kw-ttt\">morphine</span> dans les douleurs chroniques non cancéreuses ; dépister le mésusage et la dépendance.</p>\n      <p><strong>Réglementation.</strong> Prescription sur <span class=\"kw-def\">ordonnance sécurisée</span> ; durée maximale <span class=\"kw-chiffre\">28 jours</span> (<span class=\"kw-chiffre\">7 jours</span> pour <span class=\"kw-clinique\">les</span> formes injectables) ; délivrance fractionnée du <span class=\"kw-ttt\">fentanyl</span> (14 j transdermique, 7 j transmuqueux) ; <strong>renouvellement et chevauchement interdits</strong> ; posologie en toutes lettres.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Devant un <span class=\"kw-clinique\">coma</span> avec <span class=\"kw-alerte\">myosis serré + bradypnée</span>, évoquer un surdosage en <span class=\"kw-ttt\">opioïdes</span> : arrêt de l'opioïde, ventilation, <span class=\"kw-ttt\">naloxone</span> en titration — objectif FR &gt;<span class=\"kw-chiffre\"> 10-15/min</span> sans viser le réveil complet (risque de syndrome de <span class=\"kw-ttt\">sevrage</span>).</div>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le laxatif est coprescrit systématiquement à tout opioïde fort, quelles que soient la dose et la durée — la <span class=\"kw-clinique\">constipation</span> ne connaît <strong>pas</strong> de phénomène de tolérance.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 135 — <span class=\"kw-ttt\">Antalgique</span> · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>","frequence":5}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-29-0.php","label":"Collège (COFER) — Item cours 1 29 0"},{"href":"https://pharmacomedicale.org/medicaments/par-specialites/item/anti-hypertenseurs-points-essentiels","label":"Anti hypertenseurs points essentiels"},{"href":"https://www.sfcardio.fr/page/chapitre-22-item-330-prescription-et-surveillance-des-classes-de-medicaments-les-plus#antivitamines","label":"SFC — Chapitre 22 item 330 prescription et surveillance des classes de medicaments les plus"},{"href":"http://medicalcul.free.fr/n4tscore.html","label":"N4tscore"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/62.%20Accidents%20h%C3%A9morragiques%20des%20anticoagulants.pdf","label":"CeMIR — 62. accidents hémorragiques des anticoagulants"},{"href":"https://radiopaedia.org/articles/psoas-haematoma","label":"Radiopaedia : Psoas haematoma"},{"href":"https://pharmacomedicale.org/medicaments/par-specialites/item/corticoides-locaux","label":"Corticoides locaux"},{"href":"https://pharmacomedicale.org/medicaments/par-specialites/category/antalgiques-non-opiaces","label":"Antalgiques non opiaces"},{"href":"https://pharmacomedicale.org/medicaments/par-specialites/item/opiaces-les-points-essentiels","label":"Opiaces les points essentiels"},{"href":"https://pharmacomedicale.org/medicaments/par-specialites/item/opiaces-faibles","label":"Opiaces faibles"},{"href":"https://pharmacomedicale.org/medicaments/par-specialites/item/opiaces-forts","label":"Opiaces forts"},{"href":"https://pharmacomedicale.org/medicaments/par-specialites/category/opiaces-copy","label":"Opiaces copy"},{"href":"https://www.lecofer.org/item-cours-1-10-0.php","label":"Collège (COFER) — Item cours 1 10 0"},{"href":"https://campus.neurochirurgie.fr/article1603.html","label":"Collège — Article1603"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/16-ch07-071-084-9782294769580.pdf","label":"CeMIR — 16 ch07 071 084 9782294769580"}],"cards":[{"i":"0a465d736719","n":330,"o":"330-1","u":"Prise en charge","t":"Anti-inflammatoires non stéroïdiens et les corticoïdes par voie générale ou locale : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quel est le mécanisme d'action général des Anti-Inflammatoires Non Stéroïdiens (AINS) ?","a":"<p>Les AINS agissent en inhibant les <strong>cyclo-oxygénases (COX-1 et COX-2)</strong>, ce qui bloque la production des <strong>prostanoïdes</strong> (prostaglandines et thromboxanes) issus de l'acide arachidonique.</p>"},{"i":"5c416e814424","n":330,"o":"330-1","u":"Prise en charge","t":"Anti-inflammatoires non stéroïdiens et les corticoïdes par voie générale ou locale : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les rôles physiologiques respectifs des enzymes COX-1 et COX-2 dans l'organisme, et les conséquences de leur inhibition par les AINS ?","a":"<ul><li>La <strong>COX-1</strong> est constitutive et assure la protection de la muqueuse gastrique, le maintien de la perfusion rénale et la production de thromboxane proagrégant. Son inhibition provoque un <strong>ulcère gastro-duodénal</strong>, une <strong>insuffisance rénale</strong> et un effet anti-agrégant.</li><li>La <strong>COX-2</strong> est inductible dans l'inflammation et contribue à la fièvre, la douleur, l'inflammation, la perfusion rénale et la protection vasculaire. Son inhibition entraîne un effet <strong>anti-pyrétique</strong>, <strong>antalgique</strong> et <strong>anti-inflammatoire</strong>, mais peut aussi augmenter le <strong>risque pro-thrombotique</strong>.</li></ul>"},{"i":"7ada745c752a","n":330,"o":"330-1","u":"Prise en charge","t":"Anti-inflammatoires non stéroïdiens et les corticoïdes par voie générale ou locale : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les interactions médicamenteuses importantes des AINS, en particulier celles augmentant le risque hémorragique ou rénal ?","a":"<ul><li><strong>Anticoagulants oraux (AVK)</strong> : Association contre-indiquée avec le piroxicam et l'aspirine à dose anti-inflammatoire ; déconseillée avec les autres AINS (risque hémorragique).</li><li><strong>Antiagrégants plaquettaires</strong> et <strong>ISRS</strong> : Augmentation du risque d'hémorragie digestive.</li><li><strong>Lithium</strong> : Élévation de la lithémie.</li><li><strong>IEC/ARA2 + diurétiques</strong> : Risque d'<strong>insuffisance rénale aiguë</strong> chez le sujet âgé ou déshydraté (le \"trépied\" néphrotoxique).</li><li><strong>Méthotrexate</strong> à forte dose : Augmentation de sa toxicité.</li></ul>"},{"i":"862ff79d5188","n":330,"o":"330-1","u":"Prise en charge","t":"Anti-inflammatoires non stéroïdiens et les corticoïdes par voie générale ou locale : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelle est la règle d'or pour la prescription des corticoïdes et quelles sont les complications à surveiller même lors d'une corticothérapie courte ?","a":"<p>La règle d'or est de prescrire la <strong>dose la plus faible</strong> possible et pour la <strong>durée la plus courte</strong> possible. Même une corticothérapie courte (<strong>moins de 21 jours</strong>) impose une surveillance des complications précoces : aggravation d'une infection active, anguillulose maligne, déséquilibre du diabète, décompensation d'insuffisance cardiaque, HTA, ostéonécrose, troubles psychiatriques.</p>"},{"i":"b888ea3e6e38","n":330,"o":"330-1","u":"Prise en charge","t":"Anti-inflammatoires non stéroïdiens et les corticoïdes par voie générale ou locale : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les effets indésirables majeurs des corticoïdes sur les systèmes oculaire, neuropsychique et ostéo-articulaire ?","a":"<ul><li><strong>Oculaire</strong> : <strong>Cataracte sous-capsulaire postérieure</strong>, glaucome/hypertension intra-oculaire.</li><li><strong>Neuropsychique</strong> : Insomnie, excitation, troubles psychiatriques (précoces à fortes doses).</li><li><strong>Ostéo-articulaire</strong> : <strong>Ostéoporose cortico-induite</strong>, <strong>ostéonécrose aseptique de la tête fémorale</strong>, rupture tendineuse, retard de croissance.</li></ul>"},{"i":"c8f210f073b5","n":330,"o":"330-1","u":"Prise en charge","t":"Anti-inflammatoires non stéroïdiens et les corticoïdes par voie générale ou locale : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Dans quelles situations les AINS sont-ils formellement contre-indiqués ?","a":"<ul><li><strong>Ulcère gastro-duodénal évolutif</strong>, antécédents d'UGD ou d'hémorragie digestive récurrente.</li><li>Insuffisance rénale sévère, insuffisance hépatocellulaire sévère, insuffisance cardiaque sévère.</li><li>Infection évolutive, maladie hémorragique, allergie/syndrome de Widal.</li><li><strong>Grossesse à partir du 6e mois (24 SA)</strong>, pour tous les AINS et toutes les voies d'administration (sauf le collyre).</li><li>Pour les <strong>coxibs et le diclofénac</strong> : contre-indication durant toute la grossesse, et en cas d'antécédents d'AVC/AIT, de cardiopathie ischémique ou d'AOMI.</li></ul>"},{"i":"df91b3b0438f","n":330,"o":"330-1","u":"Prise en charge","t":"Anti-inflammatoires non stéroïdiens et les corticoïdes par voie générale ou locale : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les principaux effets indésirables des AINS sur les systèmes digestif, rénal et cardiovasculaire ?","a":"<ul><li><strong>Digestif</strong> : Épigastralgies, dyspepsie, <strong>ulcère gastro-duodénal</strong> (souvent asymptomatique), ulcérations du grêle et du côlon (potentielle perforation, hémorragie).</li><li><strong>Rénal</strong> : <strong>Insuffisance Rénale Aiguë fonctionnelle</strong> (en particulier chez le sujet âgé, hypovolémique), néphropathie tubulo-interstitielle immuno-allergique, nécrose papillaire, <strong>hyperkaliémie</strong>, rétention hydrosodée (HTA, œdème).</li><li><strong>Cardiovasculaire</strong> : HTA, décompensation d'une insuffisance cardiaque, <strong>thrombose artérielle</strong> (surtout avec les coxibs et le diclofénac).</li></ul>"},{"i":"e9d7256404cb","n":330,"o":"330-1","u":"Prise en charge","t":"Anti-inflammatoires non stéroïdiens et les corticoïdes par voie générale ou locale : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les principaux effets indésirables des corticoïdes par voie générale sur les systèmes cutané, métabolique et infectieux ?","a":"<ul><li><strong>Cutané</strong> : Atrophie cutanée, vergetures, <strong>purpura de Bateman</strong> (même à faible dose).</li><li><strong>Métabolique</strong> : <strong>Obésité facio-tronculaire</strong>, prise de poids, <strong>décompensation d'un diabète</strong>, hyperlipidémie.</li><li><strong>Infectieux</strong> : Réactivation d'infection latente (tuberculose, anguillulose, herpès), infections opportunistes (pneumocystose).</li></ul>"},{"i":"07f674600f4b","n":330,"o":"330-2","u":"Prise en charge","t":"Diurétiques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont le mécanisme d'action, les indications et les principaux effets sur la kaliémie des diurétiques épargneurs de potassium ?","a":"<p>Les diurétiques épargneurs de potassium agissent sur le <strong>tube collecteur</strong> :</p><ul><li>La <strong>spironolactone</strong> est un anti-aldostérone.</li><li>L'<strong>amiloride</strong> inhibe le canal ENaC.</li></ul><p>Ils provoquent une <strong>hyperkaliémie</strong>. Leurs indications principales sont l'<strong>insuffisance cardiaque à FEVG altérée NYHA 2-4</strong>, l'<strong>hyperaldostéronisme primaire</strong> et la <strong>cirrhose œdémato-ascitique</strong>.</p>"},{"i":"2ce64d72db07","n":330,"o":"330-2","u":"Prise en charge","t":"Diurétiques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les principaux effets indésirables des diurétiques épargneurs de potassium ?","a":"<p>Les principaux effets indésirables des diurétiques épargneurs de potassium sont :</p><ul><li>Une <strong>hyperkaliémie</strong></li><li>Une <strong>insuffisance rénale</strong></li></ul><p>La <strong>spironolactone</strong> peut spécifiquement causer une <strong>gynécomastie</strong>, des troubles menstruels et une dysfonction érectile.</p>"},{"i":"5a6e2fb60d39","n":330,"o":"330-2","u":"Prise en charge","t":"Diurétiques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelle surveillance biologique doit être mise en place chez un patient sous diurétiques ?","a":"<p>La surveillance doit comporter :</p><ul><li>Un <strong>bilan pré-thérapeutique</strong> : <strong>créatininémie + DFG</strong>, <strong>ionogramme sanguin</strong>, uricémie, glycémie.</li><li>Un <strong>ionogramme sanguin</strong> à <strong>J15</strong>, <strong>M1</strong>, puis <strong>1 à 2 fois par an</strong>, et à chaque modification de posologie ou événement intercurrent.</li></ul><p>Un <strong>régime hyposodé</strong> est toujours associé.</p>"},{"i":"6dc63a27bd83","n":330,"o":"330-2","u":"Prise en charge","t":"Diurétiques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont le mécanisme d'action, les indications et les principaux effets sur la kaliémie des diurétiques de l'anse et des thiazidiques ?","a":"<ul><li>Les <strong>diurétiques de l'anse</strong> (ex: furosémide, bumétanide) inhibent le <strong>co-transporteur NKCC2</strong> dans la <strong>branche ascendante de l'anse de Henlé</strong>. Ils provoquent une <strong>hypokaliémie sévère</strong> et sont indiqués en cas de <strong>surcharge hydrosodée</strong>, étant les seuls actifs si le DFG est < 30 mL/min.</li><li>Les <strong>thiazidiques</strong> (ex: hydrochlorothiazide, indapamide) inhibent le <strong>co-transporteur NaCl</strong> dans le <strong>tube contourné distal</strong>. Ils entraînent une <strong>hypokaliémie</strong> et sont indiqués dans l'<strong>HTA</strong>, sauf si le DFG est < 30 mL/min.</li></ul>"},{"i":"c925af22e3f5","n":330,"o":"330-2","u":"Prise en charge","t":"Diurétiques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les interactions médicamenteuses et les causes d'échec des diurétiques ?","a":"<p>Les principales interactions et causes d'échec des diurétiques sont :</p><ul><li>La diminution de la clairance du <strong>lithium</strong>.</li><li>Les <strong>AINS</strong> qui réduisent l'effet diurétique.</li><li>Les médicaments allongeant le <strong>QT</strong>, l'hypokaliémie favorisant la <strong>torsade de pointe</strong>.</li><li>La <strong>grossesse</strong> est une contre-indication en raison du risque d'hypoperfusion fœtale.</li><li>L'<strong>échec</strong> est fréquent si le <strong>régime hyposodé n'est pas suivi</strong>.</li><li>L'<strong>échec</strong> peut survenir si des <strong>thiazidiques</strong> sont utilisés à tort alors que le DFG est <strong>inférieur à 30 mL/min</strong>.</li></ul>"},{"i":"e83380b94369","n":330,"o":"330-2","u":"Prise en charge","t":"Diurétiques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quel est le mécanisme d'action et les indications principales de l'acétazolamide ?","a":"<p>L'acétazolamide agit sur l'<strong>anhydrase carbonique</strong> au niveau du <strong>tube contourné proximal</strong>. Il est notamment indiqué dans le <strong>glaucome aigu</strong> et le <strong>mal des montagnes</strong>.</p>"},{"i":"f3881c4b9b45","n":330,"o":"330-2","u":"Prise en charge","t":"Diurétiques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les principaux effets indésirables des diurétiques de l'anse et des thiazidiques ?","a":"<p>Les <strong>diurétiques de l'anse</strong> et les <strong>thiazidiques</strong> peuvent entraîner :</p><ul><li>Une <strong>déshydratation extracellulaire</strong></li><li>Une <strong>hyponatrémie</strong></li><li>Une <strong>hypokaliémie</strong></li><li>Une <strong>hypomagnésémie</strong></li><li>Une <strong>hyperuricémie</strong></li><li>Une <strong>hyperglycémie</strong></li></ul><p>Les <strong>thiazidiques</strong> peuvent en plus provoquer une <strong>hypercalcémie</strong> et un <strong>effet photosensibilisant</strong>.</p>"},{"i":"1a9af08c2666","n":330,"o":"330-3","u":"Prise en charge","t":"Bêta-bloquants : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les effets pharmacologiques des bêta-bloquants sur le cœur ?","a":"<p>Via l'antagonisme des récepteurs β1, les bêta-bloquants ont des effets suivants :</p><ul><li><strong>Inotrope négatif</strong> (diminution de la contractilité myocardique)</li><li><strong>Chronotrope négatif</strong> (diminution de la fréquence cardiaque)</li><li><strong>Dromotrope négatif</strong> (diminution de la conduction auriculoventriculaire)</li><li><strong>Bathmotrope négatif</strong> (diminution de l'excitabilité myocardique)</li></ul>"},{"i":"2a44a5d9dc04","n":330,"o":"330-3","u":"Prise en charge","t":"Bêta-bloquants : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les indications principales des bêta-bloquants ?","a":"<p>Les indications principales des bêta-bloquants incluent :</p><ul><li><strong>Insuffisance cardiaque à FEVG altérée</strong> (avec certains bêta-bloquants spécifiques)</li><li><strong>Post-Infarctus Du Myocarde (IDM)</strong> et <strong>Syndrome Coronarien Aigu (SCA)</strong></li><li><strong>Angor stable</strong> (sauf spasme coronaire)</li><li><strong>Troubles du rythme cardiaque</strong> et <strong>Fibrillation Auriculaire (FA) permanente</strong> (pour le contrôle de fréquence)</li><li><strong>Hypertension Artérielle (HTA)</strong>, en présence d'une indication associée</li><li><strong>Migraine</strong> (traitement de fond)</li><li><strong>Hyperthyroïdie</strong></li><li><strong>Tremblement essentiel</strong></li><li><strong>Glaucome à angle ouvert</strong></li><li><strong>Prévention de la rupture de varices œsophagiennes</strong></li></ul>"},{"i":"4aa2bc18ea32","n":330,"o":"330-3","u":"Prise en charge","t":"Bêta-bloquants : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les contre-indications absolues des bêta-bloquants ?","a":"<p>Les contre-indications absolues des bêta-bloquants sont :</p><ul><li><strong>Asthme</strong></li><li><strong>Bloc Auriculo-Ventriculaire (BAV) de grade 2 ou 3 non appareillé</strong></li><li><strong>Bradycardie symptomatique</strong> ou <strong>hypotension symptomatique</strong></li><li><strong>Insuffisance cardiaque sévère décompensée</strong></li><li><strong>Angor de Prinzmetal</strong></li><li><strong>Syndrome de Raynaud</strong></li><li><strong>Myasthénie</strong></li></ul>"},{"i":"ee260ecc14a9","n":330,"o":"330-3","u":"Prise en charge","t":"Bêta-bloquants : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"En ce qui concerne l'hypertension artérielle, quelle est la particularité d'utilisation des bêta-bloquants ?","a":"<p>Dans l'HTA, les bêta-bloquants ne sont utilisés à l'initiation que s'il existe une <strong>indication associée</strong> (ex: insuffisance cardiaque, coronaropathie, FA permanente, grossesse). La <strong>monothérapie bêta-bloquante n'est pas recommandée</strong> pour l'HTA seule.</p>"},{"i":"f2ec1058ef11","n":330,"o":"330-3","u":"Prise en charge","t":"Bêta-bloquants : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les principaux effets indésirables des bêta-bloquants ?","a":"<p>Les principaux effets indésirables des bêta-bloquants sont :</p><ul><li><strong>Asthénie</strong></li><li><strong>Bradycardie sinusale</strong> et <strong>troubles de conduction</strong></li><li><strong>Refroidissement des extrémités</strong></li><li>Aggravation d'une <strong>BPCO</strong>, d'une <strong>Artériopathie Oblitérante des Membres Inférieurs (AOMI)</strong> ou d'un <strong>psoriasis</strong></li><li><strong>Insomnie</strong> et <strong>cauchemars</strong></li><li><strong>Dysfonction érectile</strong></li><li><strong>Masquage des signes d'hypoglycémie</strong> chez le patient diabétique</li></ul>"},{"i":"ffa484d3657a","n":330,"o":"330-3","u":"Prise en charge","t":"Bêta-bloquants : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quel est le mécanisme d'action général des bêta-bloquants ?","a":"<p>Les bêta-bloquants agissent en tant qu'<strong>antagonistes des récepteurs β-adrénergiques</strong>.</p>"},{"i":"13c0e3edc80e","n":330,"o":"330-4","u":"Prise en charge","t":"Médicaments du système rénine-angiotensine : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les principaux effets indésirables des IEC, mémorisés par le moyen mnémotechnique CHARLOTTE ?","a":"<ul><li><strong>Céphalée</strong>.</li><li><strong>Hyperkaliémie</strong> (par diminution de l'aldostérone).</li><li><strong>Agueusie</strong> (surtout avec le captopril).</li><li>Atteinte <strong>rénale</strong> (insuffisance rénale, rare si CI et surveillance respectées).</li><li><strong>Leucopénie</strong> (neutropénie, agranulocytose, surtout avec le captopril).</li><li><strong>Œdème bradykinique</strong> (plus spécifique des IEC, avec atteinte laryngée possible).</li><li><strong>Toux</strong> (5-20% des IEC, apparaissant de 1 semaine à 6 mois et cessant en 4 jours à l'arrêt).</li><li><strong>Hypotension</strong> (surtout après la première dose).</li><li><strong>Éruption cutanée</strong>.</li></ul>"},{"i":"5221af0513ca","n":330,"o":"330-4","u":"Prise en charge","t":"Médicaments du système rénine-angiotensine : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Dans quelles situations les ARA2 sont-ils préférés aux IEC ?","a":"<p>Les ARA2 sont indiqués en cas d'<strong>intolérance aux IEC</strong>, principalement due à la <strong>toux</strong> qui est un effet indésirable moins fréquent avec les ARA2. Leurs contre-indications sont similaires, à l'exception de l'antécédent d'angio-œdème, qui ne contre-indique pas les ARA2.</p>"},{"i":"6be8b5d4570a","n":330,"o":"330-4","u":"Prise en charge","t":"Médicaments du système rénine-angiotensine : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les indications principales des IEC et des ARA2 ?","a":"<ul><li><strong>Insuffisance cardiaque</strong> à FEVG diminuée (quelle que soit la NYHA).</li><li><strong>HTA</strong> (hypertension artérielle).</li><li>État post-<strong>IDM</strong> (infarctus du myocarde).</li><li><strong>Néphropathie diabétique</strong>.</li><li>Prévention secondaire cardiovasculaire.</li></ul>"},{"i":"772f18920167","n":330,"o":"330-4","u":"Prise en charge","t":"Médicaments du système rénine-angiotensine : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les interactions médicamenteuses importantes concernant les IEC et les ARA2 ?","a":"<ul><li>Non-association <strong>IEC + ARA2</strong>.</li><li><strong>Lithium</strong>.</li><li><strong>AINS</strong> (risque d'hyperkaliémie et d'insuffisance rénale).</li><li><strong>Diurétiques épargneurs de potassium</strong> et <strong>sels de potassium</strong> (risque d'hyperkaliémie).</li></ul>"},{"i":"7eb377296ac2","n":330,"o":"330-4","u":"Prise en charge","t":"Médicaments du système rénine-angiotensine : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quel est le mécanisme d'action commun des IEC et des ARA2 ?","a":"<p>Les IEC et les ARA2 diminuent l'effet de l'<strong>angiotensine II</strong>, soit en inhibant l'enzyme de conversion (IEC), soit en antagonisant son récepteur (ARA2). Cela conduit à une baisse de la <strong>vasoconstriction</strong> (diminution de la PA) et une baisse de la sécrétion d'<strong>aldostérone</strong> (diminution de la rétention hydrosodée).</p>"},{"i":"85497ecc7a88","n":330,"o":"330-4","u":"Prise en charge","t":"Médicaments du système rénine-angiotensine : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Comment interpréter une augmentation de la créatininémie sous IEC ou ARA2 ?","a":"<ul><li>Une augmentation de la créatininémie de <strong>10 à 20 %</strong> traduit l'efficacité du traitement.</li><li>Une augmentation <strong>supérieure à 30 %</strong> impose l'arrêt temporaire et la recherche d'une sténose d'artère rénale.</li><li>Une <strong>hyperkaliémie supérieure à 6 mmol/L</strong> impose également l'arrêt du traitement.</li></ul>"},{"i":"8e390c1faa9d","n":330,"o":"330-4","u":"Prise en charge","t":"Médicaments du système rénine-angiotensine : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les contre-indications absolues aux IEC et aux ARA2 ?","a":"<ul><li><strong>Allergie</strong> connue.</li><li><strong>Grossesse</strong>.</li><li><strong>Hyperkaliémie</strong>.</li><li><strong>Sténose bilatérale des artères rénales</strong>.</li><li>Pour les IEC spécifiquement : antécédent d'<strong>angio-œdème</strong>. Les ARA2 ne sont pas contre-indiqués en cas d'antécédent d'angio-œdème.</li></ul>"},{"i":"b2582e502544","n":330,"o":"330-4","u":"Prise en charge","t":"Médicaments du système rénine-angiotensine : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les modalités de surveillance d'un traitement par IEC ou ARA2 ?","a":"<p>La surveillance repose sur la mesure de la <strong>PA</strong>, la <strong>créatininémie</strong> et l'<strong>ionogramme</strong> (kaliémie, natrémie) :</p><ul><li>Avant toute prescription.</li><li>À <strong>J7-J15</strong> après l'instauration.</li><li>À chaque modification de posologie.</li><li>Les <strong>quatre premières semaines</strong> sont particulièrement critiques.</li></ul>"},{"i":"01c10450e500","n":330,"o":"330-5","u":"Prise en charge","t":"Antagonistes des canaux calciques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les effets indésirables et les contre-indications spécifiques aux antagonistes des canaux calciques bradycardisants ?","a":"<p>Les effets indésirables sont la <strong>bradycardie sinusale</strong> et les <strong>troubles de conduction</strong> (blocs sino-auriculaires, blocs auriculo-ventriculaires, blocs de branche). Les contre-indications sont le <strong>bloc auriculo-ventriculaire de grade 2 ou 3</strong> et l'<strong>insuffisance cardiaque à fraction d'éjection ventriculaire gauche altérée</strong>.</p>"},{"i":"3df10c85919f","n":330,"o":"330-5","u":"Prise en charge","t":"Antagonistes des canaux calciques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les principales indications des antagonistes des canaux calciques ?","a":"<p>Les principales indications sont l'<strong>hypertension artérielle</strong> (notamment l'hypertension systolique isolée) et l'<strong>angor</strong>.</p>"},{"i":"699f1fbc4f94","n":330,"o":"330-5","u":"Prise en charge","t":"Antagonistes des canaux calciques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quel est le mécanisme d'action général des antagonistes des canaux calciques (inhibiteurs calciques) ?","a":"<p>Les antagonistes des canaux calciques bloquent les <strong>canaux calciques voltage-dépendants</strong>, ce qui entraîne une <strong>vasodilatation</strong>.</p>"},{"i":"c0b0408e769f","n":330,"o":"330-5","u":"Prise en charge","t":"Antagonistes des canaux calciques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les effets indésirables spécifiques aux dihydropyridines ?","a":"<ul><li><strong>Céphalées</strong></li><li><strong>Vertiges</strong></li><li><strong>Flush vasomoteur</strong></li><li><strong>Œdèmes des membres inférieurs</strong></li><li><strong>Hypertrophie gingivale</strong> (en particulier avec la nifédipine)</li></ul>"},{"i":"db71a6b60185","n":330,"o":"330-5","u":"Prise en charge","t":"Antagonistes des canaux calciques : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Comment les antagonistes des canaux calciques sont-ils classés et quel est le profil pharmacologique de chaque classe ?","a":"<ul><li>Les <strong>dihydropyridines</strong> (terminaison en « <strong>-dipine</strong> » comme l'amlodipine, nicardipine, nifédipine, lercanidipine) ont une <strong>action vasculaire prédominante</strong>.</li><li>Les <strong>bradycardisants</strong> (non dihydropyridines comme le diltiazem, vérapamil) ont une <strong>action mixte</strong> à la fois <strong>vasculaire et myocardique</strong>.</li></ul>"},{"i":"09679bbc76d4","n":330,"o":"330-6","u":"Prise en charge","t":"Anti-agrégants plaquettaires : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les principaux effets indésirables et comment surveille-t-on les patients sous anti-agrégants plaquettaires ?","a":"<ul><li>Le principal effet indésirable est le <strong>risque hémorragique</strong>. Des réactions d'hypersensibilité sont également possibles.</li><li>La surveillance est essentiellement <strong>clinique</strong> pour détecter des signes d'hémorragie. Bien qu'il n'existe pas de test biologique de routine fiable pour l'efficacité, une <strong>NFS annuelle</strong> est recommandée.</li></ul>"},{"i":"2d14ee0806d0","n":330,"o":"330-6","u":"Prise en charge","t":"Anti-agrégants plaquettaires : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les principales indications des anti-agrégants plaquettaires ?","a":"<ul><li><strong>Prévention secondaire</strong> : chez les patients atteints de coronaropathie, d'artériopathie oblitérante des membres inférieurs (AOMI), ou ayant fait un accident vasculaire cérébral (AVC) ischémique.</li><li><strong>Bithérapie anti-agrégante</strong> (aspirine + inhibiteur de P2Y12) : après un syndrome coronarien aigu (SCA), sa durée varie de <strong>1 à 12 mois</strong> en fonction du risque hémorragique.</li></ul>"},{"i":"5acc8797dad3","n":330,"o":"330-6","u":"Prise en charge","t":"Anti-agrégants plaquettaires : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les contre-indications absolues aux anti-agrégants plaquettaires et les contre-indications relatives spécifiques au prasugrel ?","a":"<ul><li><strong>Contre-indications absolues</strong> : ulcère gastro-duodénal évolutif, hémorragie active, insuffisance hépatique sévère, et réactions d'hypersensibilité connues.</li><li><strong>Contre-indications relatives du prasugrel</strong> : poids < <strong>60 kg</strong> et âge > <strong>75 ans</strong>, ainsi qu'un antécédent d'AVC ou d'AIT.</li></ul>"},{"i":"9f4f18271b31","n":330,"o":"330-6","u":"Prise en charge","t":"Anti-agrégants plaquettaires : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Comment gérer les anti-agrégants plaquettaires en péri-opératoire (règle des 3-5-7) et dans quelles situations l'aspirine est-elle maintenue ?","a":"<ul><li>La <strong>règle des 3-5-7</strong> guide l'arrêt préopératoire : <strong>3 jours</strong> pour l'aspirine, <strong>5 jours</strong> pour le clopidogrel et le ticagrélor, et <strong>7 jours</strong> pour le prasugrel.</li><li>L'<strong>aspirine est maintenue chaque fois que possible</strong>, notamment en cas de risque thrombotique élevé. Un acte invasif doit être différé après la pose de stent : <strong>≥ 6 semaines</strong> pour un stent nu et <strong>3 à 6 mois</strong> pour un stent actif.</li></ul>"},{"i":"cdb0db18784d","n":330,"o":"330-6","u":"Prise en charge","t":"Anti-agrégants plaquettaires : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les mécanismes d'action des inhibiteurs de P2Y12 (anti-agrégants plaquettaires) ?","a":"<p>Les inhibiteurs de P2Y12, tels que le clopidogrel, le prasugrel et le ticagrélor, bloquent spécifiquement le <strong>récepteur plaquettaire P2Y12 à l'ADP</strong> (Adénosine Diphosphate), empêchant ainsi l'activation et l'agrégation plaquettaire dépendantes de l'ADP.</p>"},{"i":"f60dd29c2865","n":330,"o":"330-6","u":"Prise en charge","t":"Anti-agrégants plaquettaires : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quel est le mécanisme d'action de l'aspirine (anti-agrégant plaquettaire) et quelle est la cible de son action ?","a":"<p>L'aspirine inhibe de manière <strong>irréversible la COX-1</strong> des plaquettes, ce qui entraîne une baisse de la production de <strong>thromboxane A2</strong>, un puissant agrégant plaquettaire. L'effet anti-agrégant dure toute la vie de la plaquette (<strong>7 à 10 jours</strong>).</p>"},{"i":"2140e745eccf","n":330,"o":"330-7","u":"Prise en charge","t":"Héparines : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les principaux effets indésirables et contre-indications des traitements par héparines ?","a":"<p>Les principaux effets indésirables des héparines sont :</p><ul><li>L'<strong>hémorragie</strong>.</li><li>La <strong>thrombopénie induite par l'héparine (TIH)</strong>.</li><li>L'<strong>hyperkaliémie</strong> (par hypoaldostéronisme).</li><li>L'<strong>ostéoporose</strong> (en cas de traitement prolongé).</li><li>La <strong>nécrose cutanée</strong> au point d'injection.</li></ul><p>Les contre-indications incluent :</p><ul><li>L'<strong>endocardite aiguë bactérienne</strong>.</li><li>L'<strong>anesthésie péridurale/rachianesthésie</strong>.</li><li>Tout <strong>saignement actif</strong>.</li><li>Un <strong>antécédent de TIH</strong>.</li></ul>"},{"i":"3248e1dff2e4","n":330,"o":"330-7","u":"Prise en charge","t":"Héparines : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les principales indications des héparines en pratique clinique ?","a":"<p>Les héparines sont utilisées dans les <strong>situations urgentes</strong> pour leur action rapide :</p><ul><li><strong>Thrombose veineuse profonde (TVP)</strong> et <strong>embolie pulmonaire (EP)</strong>.</li><li><strong>Syndrome coronaire aigu (SCA)</strong>.</li><li><strong>Troubles du rythme</strong> nécessitant une anticoagulation (ex: fibrillation atriale).</li></ul><p>Les <strong>HBPM</strong> sont aussi largement utilisées en <strong>prophylaxie de la maladie thromboembolique veineuse</strong>.</p>"},{"i":"3eeb41bcd109","n":330,"o":"330-7","u":"Prise en charge","t":"Héparines : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Comment les héparines, qu'elles soient non fractionnées ou de bas poids moléculaire, agissent-elles pour exercer leur effet anticoagulant ?","a":"<p>Les héparines agissent en <strong>potentialisant l'antithrombine</strong>. Les chaînes d'héparine inactivent :</p><ul><li>Les <strong>héparines non fractionnées (HNF)</strong> et les <strong>héparines de bas poids moléculaire (HBPM)</strong> inactivent le <strong>facteur Xa</strong>.</li><li>Les <strong>HNF</strong>, grâce à leurs longues chaînes, peuvent également inactiver le <strong>facteur IIa (thrombine)</strong>.</li><li>Le <strong>fondaparinux</strong> est un <strong>anti-Xa exclusif</strong>.</li></ul>"},{"i":"7258a717345d","n":330,"o":"330-7","u":"Prise en charge","t":"Héparines : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Comment différencier les héparines (HNF, HBPM, fondaparinux) concernant leur voie d'administration, leur impact sur la fonction rénale et l'existence d'un antidote ?","a":"<ul><li><strong>HNF</strong> : Administration IV (sodique) ou SC (calcique). Élimination rénale faible, utilisable en cas d'insuffisance rénale sévère. Existe un antidote : le <strong>sulfate de protamine</strong>.</li><li><strong>HBPM</strong> : Administration SC (énoxaparine, tinzapaprine, nadroparine, daltéparine). Élimination rénale, <strong>contre-indiquée</strong> si <strong>clairance de la créatinine < 30 mL/min</strong>. Antidote partiel : le <strong>sulfate de protamine</strong> (partiel).</li><li><strong>Fondaparinux</strong> : Administration SC. Élimination rénale, <strong>contre-indiquée</strong> si <strong>clairance de la créatinine < 30 mL/min</strong>. <strong>Aucun antidote établi</strong>.</li></ul>"},{"i":"a0b2e1df38c4","n":330,"o":"330-7","u":"Prise en charge","t":"Héparines : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les modalités de surveillance de l'efficacité et des principaux effets indésirables des héparines ?","a":"<p>La surveillance dépend du type d'héparine :</p><ul><li><strong>Héparine Non Fractionnée (HNF)</strong> : L'efficacité est surveillée quotidiennement par le <strong>TCA</strong> (cible <strong>2 à 3 fois le témoin</strong>) ou l'<strong>activité anti-Xa</strong>, en raison de son effet imprévisible.</li><li><strong>Héparines de Bas Poids Moléculaire (HBPM) et fondaparinux</strong> : En général, pas de surveillance de l'efficacité, sauf cas particuliers (poids extrêmes, insuffisance rénale modérée, risque hémorragique).</li></ul><p>Pour la surveillance des effets indésirables :</p><ul><li><strong>Numération plaquettaire</strong> (risque de TIH) : <strong>Systématique</strong> sous HNF, <strong>non systématique</strong> sous HBPM.</li><li>Recherche de signes d'<strong>hémorragie</strong>.</li><li>Surveillance de la <strong>kaliémie</strong> (risque d'hyperkaliémie par hypoaldostéronisme).</li></ul>"},{"i":"dfedeb8b3201","n":330,"o":"330-7","u":"Prise en charge","t":"Héparines : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Comment la Thrombopénie Induite par l'Héparine (TIH) de type 2 se manifeste-t-elle et quelle est sa prise en charge en urgence ?","a":"<p>La TIH de type 2 est une complication <strong>immuno-allergique</strong> due à des anticorps anti-PF4, survenant de manière <strong>retardée (J5-J21)</strong>. Elle se caractérise par :</p><ul><li>Une <strong>thrombopénie < 100 G/L ou une chute > 50 % des plaquettes</strong>.</li><li>Un <strong>risque thrombotique très élevé (50 %)</strong>, et peut être fatale dans 30 % des cas.</li></ul><p>En urgence, devant une suspicion de TIH de type 2 (thrombopénie ou chute significative des plaquettes entre J5 et J21) :</p><ul><li><strong>Arrêt immédiat de toute source d'héparine</strong>.</li><li>Relais par un anticoagulant non héparinique (<strong>danaparoïde</strong> ou <strong>argatroban</strong>).</li><li><strong>Déclaration à la pharmacovigilance</strong>.</li><li>La <strong>transfusion de plaquettes est contre-indiquée</strong>.</li></ul>"},{"i":"56dcbb3d522d","n":330,"o":"330-8","u":"Prise en charge","t":"Anticoagulants oraux (anti-vitamine K (AVK) et anticoagulants oraux directs (AOD)) : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quel est le mécanisme d'action des Antivitamines K (AVK) et quelles sont les molécules principales utilisées ?","a":"<p>Le mécanisme d'action des AVK est le <strong>blocage hépatique de la synthèse des facteurs vitamine-K dépendants</strong> (facteurs II, VII, IX, X, ainsi que les protéines C et S).</p><ul><li>Les molécules principales sont la <strong>warfarine</strong> (Coumadine), la <strong>fluindione</strong>, et l'<strong>acénocoumarol</strong>.</li></ul>"},{"i":"936332f3adfb","n":330,"o":"330-8","u":"Prise en charge","t":"Anticoagulants oraux (anti-vitamine K (AVK) et anticoagulants oraux directs (AOD)) : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Comment est assurée la surveillance des AVK et quelles sont les cibles d'INR habituelles ?","a":"<p>La surveillance des AVK est assurée par la mesure de l'<strong>INR</strong> (International Normalized Ratio).</p><ul><li>La cible d'INR est généralement de <strong>2 à 3</strong> pour la plupart des indications.</li><li>Elle est de <strong>3 à 4,5</strong> pour les prothèses valvulaires mécaniques.</li><li>Le rythme de surveillance est de deux fois par semaine les deux premières semaines, puis au moins une fois par mois au long cours. Le premier contrôle à 48-72h ne doit pas déjà atteindre la cible pour éviter un risque de surdosage.</li></ul>"},{"i":"9fec61774aef","n":330,"o":"330-8","u":"Prise en charge","t":"Anticoagulants oraux (anti-vitamine K (AVK) et anticoagulants oraux directs (AOD)) : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les signes cliniques et la prise en charge d'un hématome du psoas, complication hémorragique des anticoagulants ?","a":"<p>L'hématome du psoas est une complication hémorragique des anticoagulants qui se manifeste par :</p><ul><li>Un <strong>psoïtis</strong> (cuisse fléchie en position antalgique).</li><li>Une <strong>cruralgie</strong> sans lombalgie.</li><li>Une <strong>déglobulisation</strong> sans saignement extériorisé.</li></ul><p>Le diagnostic est confirmé par <strong>échographie ou TDM</strong> abdomino-pelvienne (hyperdensité spontanée à la TDM). La prise en charge est une <strong>urgence</strong> et dépend du volume de l'hématome et de l'INR : elle inclut l'<strong>antagonisation</strong> de l'anticoagulant et, si l'hématome est volumineux, une <strong>embolisation radiologique</strong>.</p>"},{"i":"b41facc12e72","n":330,"o":"330-8","u":"Prise en charge","t":"Anticoagulants oraux (anti-vitamine K (AVK) et anticoagulants oraux directs (AOD)) : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les contre-indications majeures des AOD, et pourquoi l'évaluation de la fonction rénale est-elle obligatoire ?","a":"<p>Les principales contre-indications des AOD sont :</p><ul><li>La présence de <strong>valve mécanique</strong> ou un <strong>rétrécissement mitral serré</strong> (contre-indication absolue).</li><li>L'<strong>insuffisance rénale sévère</strong>.</li><li>L'<strong>atteinte hépatique Child B-C</strong>.</li><li>La <strong>grossesse</strong>.</li><li>Les <strong>interactions majeures</strong> avec les inducteurs/inhibiteurs du CYP3A4 et de la P-glycoprotéine.</li></ul><p>L'évaluation de la fonction rénale est obligatoire car les AOD ont une <strong>élimination rénale significative</strong> (dabigatran 80%, rivaroxaban 33%, apixaban 25%), ce qui nécessite une adaptation posologique en cas d'insuffisance rénale.</p>"},{"i":"be31f646425d","n":330,"o":"330-8","u":"Prise en charge","t":"Anticoagulants oraux (anti-vitamine K (AVK) et anticoagulants oraux directs (AOD)) : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quel est le mécanisme d'action des anticoagulants oraux directs (AOD) et quelles en sont les molécules principales ?","a":"<p>Les AOD agissent par <strong>inhibition directe et réversible</strong> de facteurs spécifiques de la coagulation :</p><ul><li>Le <strong>dabigatran</strong> est un inhibiteur direct du <strong>FIIa</strong> (thrombine).</li><li>Le <strong>rivaroxaban</strong> et l'<strong>apixaban</strong> sont des inhibiteurs directs du <strong>FXa</strong>.</li></ul>"},{"i":"c13578d1b596","n":330,"o":"330-8","u":"Prise en charge","t":"Anticoagulants oraux (anti-vitamine K (AVK) et anticoagulants oraux directs (AOD)) : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quels sont les critères définissant une hémorragie grave sous anticoagulants et quelle est la prise en charge d'une hémorragie grave sous AVK ?","a":"<p>Les critères d'une hémorragie grave sous anticoagulants sont :</p><ul><li>Hémorragie non contrôlable.</li><li>Instabilité hémodynamique.</li><li>Nécessité d'un geste hémostatique.</li><li>Nécessité d'une transfusion.</li><li>Localisation menaçant le pronostic vital ou fonctionnel.</li></ul><p>En cas d'hémorragie grave sous AVK, il faut <strong>antagoniser l'AVK</strong>, même si l'INR est dans la cible, par l'administration de <strong>PPSB (concentré de complexe prothrombique) + vitamine K</strong>, avec un objectif d'INR inférieur à 1,5.</p>"},{"i":"e56d45ad20e1","n":330,"o":"330-8","u":"Prise en charge","t":"Anticoagulants oraux (anti-vitamine K (AVK) et anticoagulants oraux directs (AOD)) : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Quelles sont les principales contre-indications des AVK ?","a":"<p>Les principales contre-indications des AVK sont :</p><ul><li>La <strong>grossesse</strong> (tératogènes au premier trimestre, hémorragiques au troisième trimestre).</li><li>L'<strong>insuffisance hépatique sévère</strong>.</li><li>La <strong>fibrillation atriale non valvulaire</strong> (où les AOD sont privilégiés).</li></ul>"},{"i":"fbf93c6bf6b1","n":330,"o":"330-8","u":"Prise en charge","t":"Anticoagulants oraux (anti-vitamine K (AVK) et anticoagulants oraux directs (AOD)) : connaître les mécanismes d’action, indications, effets secondaires, interactions médicamenteuses, modalités de surveillance et principales causes d’échec","q":"Comment doit-on prendre en charge un surdosage asymptomatique en AVK ?","a":"<p>La prise en charge d'un surdosage asymptomatique en AVK dépend du niveau d'INR :</p><ul><li>Si l'INR est entre <strong>4 et 6</strong> : <strong>saut de la prochaine prise</strong>.</li><li>Si l'INR est entre <strong>6 et 10</strong> : <strong>arrêt de l'AVK + vitamine K 1 à 2 mg</strong> par voie orale.</li><li>Si l'INR est <strong>supérieur à 10</strong> : <strong>arrêt de l'AVK + vitamine K 5 mg</strong> par voie orale.</li></ul>"}]};